    def test_vulkan_shape_envelope_runtime_iterator_uses_generated_cases(self):
        expected_generated_counts = {
            "attention_probability_materialization_contract.json": (16, 13),
            "batch_norm_inference_contract.json": (4, 3),
            "batch_norm_inference_materialized_contract.json": (1, 3),
            "channel_cat_contract.json": (5, 7),
            "diffusion_sdpa_contract.json": (11, 6),
            "sdpa_execution_policy_contract.json": (6, 6),
            "embedding_lookup_contract.json": (4, 4),
            "elementwise_broadcast_contract.json": (4, 3),
            "gqa_repeat_contract.json": (3, 2),
            "kv_cache_append_contract.json": (3, 5),
            "kv_cache_append_initial_contract.json": (3, 5),
            "linear_gelu_bridge_contract.json": (2, 11),
            "masked_tiny_sdpa_contract.json": (2, 7),
            "no_overlap_conv_transpose2d_contract.json": (3, 5),
            "safe_view_reshape_alias_contract.json": (2, 4),
            "safe_view_reshape_contract.json": (2, 3),
            "sdpa_score_softmax_contract.json": (4, 3),
            "small_metadata_padded_conv2d_contract.json": (1, 7),
            "small_spatial_pointwise_conv_contract.json": (147, 15),
            "token_prefix_cat_add_contract.json": (30, 6),
            "transformer_gqa_sdpa_contract.json": (4, 8),
            "vision_self_attention_sdpa_contract.json": (6, 8),
        }
        for file_name, expected_counts in expected_generated_counts.items():
            expected_legal_count, expected_negative_count = expected_counts
            spec = _load_vulkan_contract_spec(file_name)
            runtime_cases = list(
                contract_spec_utils.iter_shape_envelope_contract_cases(spec)
            )
            generated_legal_cases = [
                (case, expect_native_route)
                for section, case, expect_native_route in runtime_cases
                if section == "generated_legal_cases"
            ]
            generated_negative_cases = [
                (case, expect_native_route)
                for section, case, expect_native_route in runtime_cases
                if section == "generated_negative_cases"
            ]

            self.assertEqual(
                len(generated_legal_cases),
                expected_legal_count,
            )
            self.assertEqual(
                len(generated_negative_cases),
                expected_negative_count,
            )
            self.assertTrue(
                all(
                    expect_native_route is True
                    for _, expect_native_route in generated_legal_cases
                )
            )
            self.assertTrue(
                all(
                    expect_native_route is False
                    for _, expect_native_route in generated_negative_cases
                )
            )

    def test_vulkan_shape_envelope_uses_role_registry_key_fields(self):
        registry = contract_spec_utils.shape_envelope_role_registry()
        self.assertEqual(
            set(registry),
            {
                "attention_probability_materialization_"
                "decomposed_attention_probability_to_value_bmm",
                "batch_norm_inference_buffer_float_4d",
                "batch_norm_inference_materialized_buffer_float_4d",
                "diffusion_sdpa_sparse_attention_rows",
                "sdpa_execution_policy_sparse_rows",
                "elementwise_float_tensor_tensor_buffer_broadcast",
                "gqa_repeat_batch1_heads4_factor4_sequence100_to116_dim128",
                "kv_cache_append_initial_cache",
                "kv_cache_append_sequence_append",
                "linear_gelu_bridge_backbone_mlp_hidden384_to1536",
                "masked_tiny_sdpa_additive_float_mask",
                "no_overlap_conv_transpose2d_kernel2_stride2_float_buffer",
                "small_metadata_padded_conv2d_materialized_buffer_input_2x2",
                "small_spatial_pointwise_conv_sparse_projection_rows",
                "token_prefix_cat_add_prefix1_observed_token_set",
                "transformer_gqa_sdpa_sparse_attention_rows",
                "vision_self_attention_sdpa_sparse_attention_rows",
                "multi_input_rank4_channel_cat",
                "embedding_lookup_small_bounded",
                "safe_reshape_alias_dense_buffer_direct",
                "safe_view_materialized_direct_buffer",
                "sdpa_score_softmax_diffusion_square_scores",
            },
        )
        for adapter in registry.values():
            for callable_field in (
                "validate",
                "assignment_cases",
                "legal_cases",
                "adjacent_negative_cases",
            ):
                self.assertTrue(callable(adapter[callable_field]))
            for key_field in ("legal_key_fields", "adjacent_negative_key_fields"):
                self.assertGreater(len(adapter[key_field]), 0)
                self.assertFalse(
                    any(callable(field) for field in adapter[key_field])
                )
            self.assertGreater(len(adapter["assignment_coverage_fields"]), 0)
            self.assertFalse(
                any(callable(field) for field in adapter["assignment_coverage_fields"])
            )
        assignment_generators = {
            adapter["assignment_cases"]
            for adapter in registry.values()
        }
        self.assertEqual(len(assignment_generators), 1)

        source = self._repo_text(
            "test",
            "vulkan_contract_specs",
            "contract_spec_utils.py",
        )
        self.assertIn("SHAPE_ENVELOPE_ROLE_REGISTRY", source)
        self.assertIn("_generated_shape_envelope_assignment_cases", source)
        self.assertIn("assignment_coverage_fields", source)
