@unittest.skipUnless(torch.is_vulkan_available(),
                     "Vulkan backend must be available for these tests.")
class TestVulkanRewritePass(VulkanDiagnosticLogMixin, TestCase):
    @staticmethod
    def validate_transformed_module(
            # To please flake
            self,
            pattern_count_map,
            data_shape,
            prepack_removal=False,
            fuse_clamping_ops=False):
        module_instance = self
        scripted_model = torch.jit.script(module_instance)
        scripted_model.eval()
        input_data = torch.normal(1, 20, size=data_shape)
        scripted_model(input_data)
        torch._C._jit_pass_vulkan_insert_prepacked_ops(scripted_model._c)
        if fuse_clamping_ops or prepack_removal:
            scripted_model._c = torch._C._freeze_module(scripted_model._c)
        if fuse_clamping_ops:
            torch._C._jit_pass_vulkan_fuse_clamp_w_prepacked_conv(scripted_model._c)
        if prepack_removal:
            torch._C._jit_pass_vulkan_fold_prepacking_ops(scripted_model._c)

        buffer = io.BytesIO()
        torch.jit.save(scripted_model, buffer)
        buffer.seek(0)
        deserialized_scripted_model = torch.jit.load(buffer)
        for pattern, v in pattern_count_map.items():
            if (v == 0):
                FileCheck().check(pattern).run(deserialized_scripted_model.graph)
            elif (v == -1):
                FileCheck().check_not(pattern).run(deserialized_scripted_model.graph)
            else:
                FileCheck().check_count(pattern, v, exactly=True).run(deserialized_scripted_model.graph)

    def test_conv(self):
        # Conv params
        batch_size = 2
        input_channels_per_group = 6
        height = 16
        width = 16
        output_channels_per_group = 6
        groups = 4
        kernel_h = kernel_w = 3
        stride_h = stride_w = 1
        pad_h = pad_w = 1
        dilation = 1
        input_channels = input_channels_per_group * groups
        output_channels = output_channels_per_group * groups
        strides = (stride_h, stride_w)
        paddings = (pad_h, pad_w)
        dilations = (dilation, dilation)
        conv_weight_shape = (output_channels, input_channels_per_group, kernel_h, kernel_w)
        conv_bias_shape = (output_channels)

        class Conv2D(torch.nn.Module):
            def __init__(self) -> None:
                super().__init__()
                self.weight = torch.nn.Parameter(torch.rand(conv_weight_shape), requires_grad=False)
                self.bias = torch.nn.Parameter(torch.rand(conv_bias_shape), requires_grad=False)
                self.strides = strides
                self.paddings = paddings
                self.dilations = dilations
                self.groups = groups

            def forward(self, x):
                return F.conv2d(x, self.weight, self.bias,
                                self.strides, self.paddings, self.dilations, self.groups)

        data_shape = (batch_size, input_channels, height, width)
        pattern_count_map = {"Tensor = aten::conv2d": -1,
                             "vulkan_prepack::create_conv2d_context": 1,
                             "vulkan_prepack::run_conv2d_context": 1}
        TestVulkanRewritePass.validate_transformed_module(Conv2D(), pattern_count_map, data_shape)

        class Conv2DRelu(torch.nn.Module):
            def __init__(self) -> None:
                super().__init__()
                self.weight = torch.nn.Parameter(torch.rand(conv_weight_shape), requires_grad=False)
                self.bias = torch.nn.Parameter(torch.rand(conv_bias_shape), requires_grad=False)
                self.strides = strides
                self.paddings = paddings
                self.dilations = dilations
                self.groups = groups

            def forward(self, x):
                o = F.conv2d(x, self.weight, self.bias,
                             self.strides, self.paddings, self.dilations, self.groups)
                o = F.relu(o)
                return o

        data_shape = (batch_size, input_channels, height, width)
        pattern_count_map = {"Tensor = aten::conv2d": -1,
                             "vulkan_prepack::create_conv2d_context": 1,
                             "vulkan_prepack::run_conv2d_context": 1}
        TestVulkanRewritePass.validate_transformed_module(
            Conv2DRelu(), pattern_count_map, data_shape)

        pattern_count_map["aten::relu"] = 1
        pattern_count_map["vulkan_prepack::create_conv2d_context"] = -1
        TestVulkanRewritePass.validate_transformed_module(
            Conv2DRelu(),
            pattern_count_map,
            data_shape,
            prepack_removal=True)
        pattern_count_map["aten::relu"] = -1
        TestVulkanRewritePass.validate_transformed_module(
            Conv2DRelu(),
            pattern_count_map,
            data_shape,
            prepack_removal=True,
            fuse_clamping_ops=True)


        class Conv2DHardtanh(torch.nn.Module):
            def __init__(self) -> None:
                super().__init__()
                self.weight = torch.nn.Parameter(torch.rand(conv_weight_shape), requires_grad=False)
                self.bias = torch.nn.Parameter(torch.rand(conv_bias_shape), requires_grad=False)
                self.strides = strides
                self.paddings = paddings
                self.dilations = dilations
                self.groups = groups

            def forward(self, x):
                o = F.conv2d(x, self.weight, self.bias,
                             self.strides, self.paddings, self.dilations, self.groups)
                o = F.hardtanh(o)
                return o

        data_shape = (batch_size, input_channels, height, width)
        pattern_count_map = {"Tensor = aten::conv2d": -1,
                             "vulkan_prepack::create_conv2d_context": 1,
                             "vulkan_prepack::run_conv2d_context": 1}
        TestVulkanRewritePass.validate_transformed_module(Conv2DHardtanh(), pattern_count_map, data_shape)
        pattern_count_map["aten::hardtanh"] = 1
        pattern_count_map["vulkan_prepack::create_conv2d_context"] = -1
        TestVulkanRewritePass.validate_transformed_module(
            Conv2DHardtanh(),
            pattern_count_map,
            data_shape,
            prepack_removal=True)
        pattern_count_map["aten::hardtanh"] = -1
        TestVulkanRewritePass.validate_transformed_module(
            Conv2DRelu(),
            pattern_count_map,
            data_shape,
            prepack_removal=True,
            fuse_clamping_ops=True)

class DepthAnythingStyleResidualConvUnit(nn.Module):
    def __init__(self, features):
        super().__init__()
        self.conv1 = nn.Conv2d(features, features, kernel_size=3, padding=1)
        self.conv2 = nn.Conv2d(features, features, kernel_size=3, padding=1)
        self.activation = nn.ReLU(inplace=False)

    def forward(self, x):
        out = self.activation(x)
        out = self.conv1(out)
        out = self.activation(out)
        out = self.conv2(out)
        return out + x


class DepthAnythingStyleFeatureFusionBlock(nn.Module):
    def __init__(self, features):
        super().__init__()
        self.residual_1 = DepthAnythingStyleResidualConvUnit(features)
        self.residual_2 = DepthAnythingStyleResidualConvUnit(features)
        self.out_conv = nn.Conv2d(features, features, kernel_size=1)

    def forward(self, *xs, size=None):
        output = xs[0]

        if len(xs) == 2:
            output = output + self.residual_1(xs[1])

        output = self.residual_2(output)
        if size is None:
            output = F.interpolate(
                output,
                scale_factor=2,
                mode="bilinear",
                align_corners=True)
        else:
            output = F.interpolate(
                output,
                size=size,
                mode="bilinear",
                align_corners=True)
        return self.out_conv(output)


class DepthAnythingStyleReadoutProject(nn.Module):
    def __init__(self, embed_dim):
        super().__init__()
        self.project = nn.Sequential(
            nn.Linear(2 * embed_dim, embed_dim),
            nn.GELU())

    def forward(self, tokens, cls_token):
        readout = cls_token.unsqueeze(1).expand_as(tokens)
        return self.project(torch.cat((tokens, readout), dim=-1))


class DepthAnythingStyleMiniDPTHead(nn.Module):
    # Reduced-width DPT head modeled on Depth Anything V2's decoder topology.
    def __init__(
            self,
            embed_dim=16,
            features=8,
            out_channels=(8, 8, 8, 8),
            use_clstoken=False,
            scratch_bias=True):
        super().__init__()
        self.use_clstoken = use_clstoken
        self.projects = nn.ModuleList(
            [nn.Conv2d(embed_dim, channels, kernel_size=1)
             for channels in out_channels])
        self.resize_layers = nn.ModuleList([
            nn.ConvTranspose2d(out_channels[0], out_channels[0], kernel_size=4, stride=4),
            nn.ConvTranspose2d(out_channels[1], out_channels[1], kernel_size=2, stride=2),
            nn.Identity(),
            nn.Conv2d(out_channels[3], out_channels[3], kernel_size=3, stride=2, padding=1),
        ])
        if use_clstoken:
            self.readout_projects = nn.ModuleList(
                [DepthAnythingStyleReadoutProject(embed_dim)
                 for _ in out_channels])

        self.scratch_layers = nn.ModuleList(
            [nn.Conv2d(
                channels,
                features,
                kernel_size=3,
                padding=1,
                bias=scratch_bias)
             for channels in out_channels])

        self.refinenet4 = DepthAnythingStyleFeatureFusionBlock(features)
        self.refinenet3 = DepthAnythingStyleFeatureFusionBlock(features)
        self.refinenet2 = DepthAnythingStyleFeatureFusionBlock(features)
        self.refinenet1 = DepthAnythingStyleFeatureFusionBlock(features)

        self.output_conv1 = nn.Conv2d(features, features // 2, kernel_size=3, padding=1)
        self.output_conv2 = nn.Sequential(
            nn.Conv2d(features // 2, features // 2, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(features // 2, 1, kernel_size=1),
            nn.ReLU(inplace=True))

    def forward(self, out_features, patch_h, patch_w):
        out = []
        for i, x in enumerate(out_features):
            if self.use_clstoken:
                x, cls_token = x
                x = self.readout_projects[i](x, cls_token)
            else:
                x = x[0]

            x = x.permute(0, 2, 1).reshape(
                (x.shape[0], x.shape[-1], patch_h, patch_w))
            x = self.projects[i](x)
            x = self.resize_layers[i](x)
            out.append(x)

        layer_1, layer_2, layer_3, layer_4 = out
        layer_1_rn = self.scratch_layers[0](layer_1)
        layer_2_rn = self.scratch_layers[1](layer_2)
        layer_3_rn = self.scratch_layers[2](layer_3)
        layer_4_rn = self.scratch_layers[3](layer_4)

        path_4 = self.refinenet4(layer_4_rn, size=layer_3_rn.shape[2:])
        path_3 = self.refinenet3(path_4, layer_3_rn, size=layer_2_rn.shape[2:])
        path_2 = self.refinenet2(path_3, layer_2_rn, size=layer_1_rn.shape[2:])
        path_1 = self.refinenet1(path_2, layer_1_rn)

        out = self.output_conv1(path_1)
        out = F.interpolate(
            out,
            (int(patch_h * 14), int(patch_w * 14)),
            mode="bilinear",
            align_corners=True)
        return self.output_conv2(out)

@unittest.skipUnless(torch.is_vulkan_available(),
                     "Vulkan backend must be available for these tests.")
class TestVulkanEagerRuntime(VulkanDiagnosticLogMixin, TestCase):
    def _to_vulkan(self, value, device="vulkan"):
        if torch.is_tensor(value):
            return value.to(device)
        if isinstance(value, tuple):
            return tuple(self._to_vulkan(v, device) for v in value)
        if isinstance(value, list):
            return [self._to_vulkan(v, device) for v in value]
        return value

    def _vulkan_device(self, index=None):
        if index is None:
            index = torch.vulkan.current_device()
        return torch.device("vulkan", index)

    def _require_multiple_vulkan_devices(self):
        if torch.vulkan.device_count() < 2:
            self.skipTest("Multiple Vulkan devices are required for this test.")

    def _working_vulkan_device_indices(self):
        working = []
        with torch.inference_mode():
            for device_index in range(torch.vulkan.device_count()):
                try:
                    sample = torch.randn(1).to(self._vulkan_device(device_index))
                    sample.cpu()
                except RuntimeError:
                    continue
                working.append(device_index)
        return working

    def _non_default_working_vulkan_device_index(self):
        default_device = torch.vulkan.current_device()
        for device_index in self._working_vulkan_device_indices():
            if device_index != default_device:
                return device_index
        self.skipTest(
            "No non-default Vulkan device completed a simple round-trip on this "
            "machine.")

    def _working_vulkan_device_group(self, min_devices=2):
        working_devices = self._working_vulkan_device_indices()
        if len(working_devices) < min_devices:
            self.skipTest(
                f"At least {min_devices} working Vulkan devices are required for "
                "this test.")
        return working_devices[:min_devices]

    def _linear_capable_vulkan_device_indices(self):
        capable = []
        torch.manual_seed(0)
        with torch.inference_mode():
            for device_index in range(torch.vulkan.device_count()):
                try:
                    device = self._vulkan_device(device_index)
                    module = nn.Linear(4, 3).eval().to(device)
                    sample = torch.randn(2, 4).to(device)
                    module(sample).cpu()
                except RuntimeError:
                    continue
                capable.append(device_index)
        return capable

    def _linear_capable_vulkan_device_group(self, min_devices=2):
        capable_devices = self._linear_capable_vulkan_device_indices()
        if len(capable_devices) < min_devices:
            self.skipTest(
                f"At least {min_devices} Vulkan devices that can execute a "
                "Linear module are required for this test.")
        return capable_devices[:min_devices]

    def _skip_unless_large_buffer_conv3x3_supported(self):
        device_index = torch.vulkan.current_device()
        device_name = torch.vulkan.get_device_name(device_index)
        if "RX 9070" not in device_name:
            self.skipTest(
                "Large 3x3 buffer conv is currently validated only on RX 9070; "
                f"current Vulkan device is {device_name!r}.")

    def _assert_outputs_close(self, expected, actual, *, atol=1e-4, rtol=1e-4):
        if torch.is_tensor(expected):
            self.assertTrue(torch.is_tensor(actual))
            self.assertEqual(expected, actual.cpu(), atol=atol, rtol=rtol)
            return

        if isinstance(expected, tuple):
            self.assertIsInstance(actual, tuple)
            self.assertEqual(len(expected), len(actual))
            for expected_item, actual_item in zip(expected, actual):
                self._assert_outputs_close(
                    expected_item,
                    actual_item,
                    atol=atol,
                    rtol=rtol)
            return

        if isinstance(expected, list):
            self.assertIsInstance(actual, list)
            self.assertEqual(len(expected), len(actual))
            for expected_item, actual_item in zip(expected, actual):
                self._assert_outputs_close(
                    expected_item,
                    actual_item,
                    atol=atol,
                    rtol=rtol)
            return

        self.assertEqual(expected, actual)

    def _conv2d_unfold_reference(self, module, x):
        self.assertEqual(
            module.groups,
            1,
            msg="The unfold reference currently covers non-grouped conv2d only")
        weight = module.weight.detach()
        bias = module.bias.detach() if module.bias is not None else None
        batch = x.shape[0]
        out_channels = weight.shape[0]
        unfolded = F.unfold(
            x,
            weight.shape[-2:],
            dilation=module.dilation,
            padding=module.padding,
            stride=module.stride)
        output = torch.bmm(
            weight.view(out_channels, -1).unsqueeze(0).expand(batch, -1, -1),
            unfolded)
        out_height = (
            x.shape[2] + 2 * module.padding[0] -
            module.dilation[0] * (weight.shape[-2] - 1) - 1
        ) // module.stride[0] + 1
        out_width = (
            x.shape[3] + 2 * module.padding[1] -
            module.dilation[1] * (weight.shape[-1] - 1) - 1
        ) // module.stride[1] + 1
        output = output.view(batch, out_channels, out_height, out_width)
        if bias is not None:
            output = output + bias.view(1, out_channels, 1, 1)
        return output

    def _snapshot_cpu_outputs(self, value):
        if torch.is_tensor(value):
            return value.detach().cpu().clone()

        if isinstance(value, tuple):
            return tuple(self._snapshot_cpu_outputs(item) for item in value)

        if isinstance(value, list):
            return [self._snapshot_cpu_outputs(item) for item in value]

        if isinstance(value, dict):
            return {
                key: self._snapshot_cpu_outputs(item)
                for key, item in value.items()
            }

        return value

    def _clone_cpu_inputs(self, value):
        if torch.is_tensor(value):
            return value.detach().clone()

        if isinstance(value, tuple):
            return tuple(self._clone_cpu_inputs(item) for item in value)

        if isinstance(value, list):
            return [self._clone_cpu_inputs(item) for item in value]

        if isinstance(value, dict):
            return {
                key: self._clone_cpu_inputs(item)
                for key, item in value.items()
            }

        return value

    def _tensor_accuracy_summary(self, expected, actual):
        expected_cpu = expected.detach().cpu()
        actual_cpu = actual.detach().cpu()
        self.assertEqual(
            expected_cpu.shape,
            actual_cpu.shape,
            msg=(
                "Vulkan accuracy shape mismatch: "
                f"expected={tuple(expected_cpu.shape)} "
                f"actual={tuple(actual_cpu.shape)}"))

        if expected_cpu.numel() == 0:
            return {
                "max_abs": 0.0,
                "mean_abs": 0.0,
                "max_rel": 0.0,
                "nonfinite": 0,
                "bad_count": 0,
            }

        if not (
            expected_cpu.is_floating_point()
            or actual_cpu.is_floating_point()
        ):
            bad_count = int((expected_cpu != actual_cpu).sum().item())
            return {
                "max_abs": float(bad_count > 0),
                "mean_abs": float(bad_count > 0),
                "max_rel": float(bad_count > 0),
                "nonfinite": 0,
                "bad_count": bad_count,
            }

        expected_f = expected_cpu.to(torch.float64)
        actual_f = actual_cpu.to(torch.float64)
        finite_mask = torch.isfinite(expected_f) & torch.isfinite(actual_f)
        nonfinite = int((~finite_mask).sum().item())
        if finite_mask.any():
            diff = (expected_f[finite_mask] - actual_f[finite_mask]).abs()
            denom = expected_f[finite_mask].abs().clamp_min(1e-12)
            rel = diff / denom
            max_abs = float(diff.max().item())
            mean_abs = float(diff.mean().item())
            max_rel = float(rel.max().item())
        else:
            max_abs = float("inf")
            mean_abs = float("inf")
            max_rel = float("inf")

        return {
            "max_abs": max_abs,
            "mean_abs": mean_abs,
            "max_rel": max_rel,
            "nonfinite": nonfinite,
            "bad_count": 0,
        }

    def _assert_tensors_close_with_accuracy(
            self,
            expected,
            actual,
            *,
            atol,
            rtol,
            label):
        self.assertTrue(
            torch.is_tensor(actual),
            msg=f"{label}: Vulkan output is not a tensor")

        expected_cpu = expected.detach().cpu()
        actual_cpu = actual.detach().cpu()
        summary = self._tensor_accuracy_summary(expected_cpu, actual_cpu)

        if summary["nonfinite"] != 0:
            self.fail(
                f"{label}: non-finite values detected "
                f"nonfinite={summary['nonfinite']} "
                f"max_abs={summary['max_abs']:.8g} "
                f"mean_abs={summary['mean_abs']:.8g} "
                f"max_rel={summary['max_rel']:.8g}")

        if not (
            expected_cpu.is_floating_point()
            or actual_cpu.is_floating_point()
        ):
            if summary["bad_count"] != 0:
                self.fail(
                    f"{label}: exact tensor mismatch "
                    f"bad_count={summary['bad_count']}")
            return summary

        expected_f = expected_cpu.to(torch.float64)
        actual_f = actual_cpu.to(torch.float64)
        close = torch.isclose(expected_f, actual_f, atol=atol, rtol=rtol)
        bad_count = int((~close).sum().item())
        if bad_count != 0:
            self.fail(
                f"{label}: Vulkan accuracy mismatch "
                f"bad_count={bad_count}/{expected_cpu.numel()} "
                f"atol={atol} rtol={rtol} "
                f"max_abs={summary['max_abs']:.8g} "
                f"mean_abs={summary['mean_abs']:.8g} "
                f"max_rel={summary['max_rel']:.8g}")

        return summary

    def _assert_outputs_close_with_accuracy(
            self,
            expected,
            actual,
            *,
            atol=1e-4,
            rtol=1e-4,
            label="output"):
        if torch.is_tensor(expected):
            return [self._assert_tensors_close_with_accuracy(
                expected,
                actual,
                atol=atol,
                rtol=rtol,
                label=label)]

        if isinstance(expected, tuple):
            self.assertIsInstance(actual, tuple)
            self.assertEqual(len(expected), len(actual))
            summaries = []
            for index, (expected_item, actual_item) in enumerate(
                    zip(expected, actual)):
                summaries.extend(self._assert_outputs_close_with_accuracy(
                    expected_item,
                    actual_item,
                    atol=atol,
                    rtol=rtol,
                    label=f"{label}[{index}]"))
            return summaries

        if isinstance(expected, list):
            self.assertIsInstance(actual, list)
            self.assertEqual(len(expected), len(actual))
            summaries = []
            for index, (expected_item, actual_item) in enumerate(
                    zip(expected, actual)):
                summaries.extend(self._assert_outputs_close_with_accuracy(
                    expected_item,
                    actual_item,
                    atol=atol,
                    rtol=rtol,
                    label=f"{label}[{index}]"))
            return summaries

        if isinstance(expected, dict):
            self.assertIsInstance(actual, dict)
            self.assertEqual(set(expected.keys()), set(actual.keys()))
            summaries = []
            for key in sorted(expected.keys()):
                summaries.extend(self._assert_outputs_close_with_accuracy(
                    expected[key],
                    actual[key],
                    atol=atol,
                    rtol=rtol,
                    label=f"{label}.{key}"))
            return summaries

        self.assertEqual(expected, actual)
        return []

    def _assert_repeated_vulkan_accuracy(
            self,
            cases,
            *,
            repeats=3,
            variants=2,
            atol=1e-4,
            rtol=1e-4,
            drift_atol=None,
            drift_rtol=None):
        if drift_atol is None:
            drift_atol = atol
        if drift_rtol is None:
            drift_rtol = rtol

        for case in cases:
            name = case["name"]
            make_case = case["make"]
            case_atol = case.get("atol", atol)
            case_rtol = case.get("rtol", rtol)
            case_drift_atol = case.get("drift_atol", drift_atol)
            case_drift_rtol = case.get("drift_rtol", drift_rtol)
            case_repeats = case.get("repeats", repeats)
            case_variants = case.get("variants", variants)

            for variant in range(case_variants):
                with self.subTest(case=name, variant=variant):
                    cpu_fn, vulkan_fn, inputs = make_case(variant)
                    first_vulkan_output = None

                    for repeat in range(case_repeats):
                        cpu_inputs = self._clone_cpu_inputs(inputs)
                        vulkan_inputs = self._to_vulkan(
                            self._clone_cpu_inputs(inputs))
                        label = f"{name} variant={variant} repeat={repeat}"

                        with torch.inference_mode():
                            expected = self._single_threaded_cpu(
                                lambda: cpu_fn(*cpu_inputs))
                            actual = vulkan_fn(*vulkan_inputs)

                        actual_snapshot = self._snapshot_cpu_outputs(actual)
                        self._assert_outputs_close_with_accuracy(
                            expected,
                            actual_snapshot,
                            atol=case_atol,
                            rtol=case_rtol,
                            label=f"{label} cpu_reference")

                        if first_vulkan_output is None:
                            first_vulkan_output = actual_snapshot
                        else:
                            self._assert_outputs_close_with_accuracy(
                                first_vulkan_output,
                                actual_snapshot,
                                atol=case_drift_atol,
                                rtol=case_drift_rtol,
                                label=f"{label} repeated_drift")

    def _single_threaded_cpu(self, fn):
        previous_num_threads = torch.get_num_threads()
        torch.set_num_threads(1)
        try:
            return fn()
        finally:
            torch.set_num_threads(previous_num_threads)

    def _assert_vulkan_matches_cpu(self, fn, *args, atol=1e-4, rtol=1e-4):
        # Exercise the Vulkan backend in inference mode to avoid autograd
        # dispatch ambiguity with CompositeImplicitAutograd kernels.
        with torch.inference_mode():
            expected = self._single_threaded_cpu(lambda: fn(*args))
            actual = fn(*self._to_vulkan(args))

        self._assert_outputs_close(expected, actual, atol=atol, rtol=rtol)

    def _assert_known_limitation(self, fn, *args, exc_type=RuntimeError, message):
        with torch.inference_mode():
            fn(*args)
            with self.assertRaisesRegex(exc_type, message):
                fn(*self._to_vulkan(args))

    def test_repeated_accuracy_elementwise_view_and_reduction_matrix(self):
        def make_metadata_view_binary(variant):
            torch.manual_seed(1000 + variant)
            x = torch.randn(2, 5 + variant * 2, 8)
            y = torch.randn(2, 5 + variant * 2, 8)

            def fn(a, b):
                av = a[:, 1::2, :]
                bv = b[:, 1::2, :]
                return torch.relu(av + bv * 0.25) * (av - bv * 0.125)

            return fn, fn, (x, y)

        def make_dim_reduction(variant):
            torch.manual_seed(1100 + variant)
            x = torch.randn(2 + variant, 4, 7)

            def fn(t):
                return (
                    t.sum(dim=-1),
                    t.mean(dim=1),
                )

            return fn, fn, (x,)

        self._assert_repeated_vulkan_accuracy(
            [
                {
                    "name": "metadata_view_binary",
                    "make": make_metadata_view_binary,
                },
                {
                    "name": "dim_reduction_sum_mean",
                    "make": make_dim_reduction,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
            ],
            repeats=3,
            variants=2)

    def test_repeated_accuracy_linear_softmax_and_norm_matrix(self):
        def make_linear_gelu(variant):
            torch.manual_seed(1200 + variant)
            in_features = 32 + variant * 16
            out_features = 24 + variant * 8
            module_cpu = nn.Linear(in_features, out_features).eval()
            module_vulkan = nn.Linear(in_features, out_features).eval()
            module_vulkan.load_state_dict(module_cpu.state_dict())
            module_vulkan = module_vulkan.to("vulkan")
            x = torch.randn(2, 3 + variant, in_features)

            def cpu_fn(t):
                return F.gelu(module_cpu(t))

            def vulkan_fn(t):
                return F.gelu(module_vulkan(t))

            return cpu_fn, vulkan_fn, (x,)

        def make_softmax(variant):
            torch.manual_seed(1300 + variant)
            x = torch.randn(2, 3 + variant, 16 + variant * 8)

            def fn(t):
                return torch.softmax(t, dim=-1)

            return fn, fn, (x,)

        def make_layer_norm(variant):
            torch.manual_seed(1400 + variant)
            normalized_shape = 32 + variant * 16
            module_cpu = nn.LayerNorm(normalized_shape).eval()
            module_vulkan = nn.LayerNorm(normalized_shape).eval()
            module_vulkan.load_state_dict(module_cpu.state_dict())
            module_vulkan = module_vulkan.to("vulkan")
            x = torch.randn(2, 4 + variant, normalized_shape)

            return module_cpu, module_vulkan, (x,)

        self._assert_repeated_vulkan_accuracy(
            [
                {
                    "name": "linear_gelu",
                    "make": make_linear_gelu,
                    "atol": 3e-4,
                    "rtol": 3e-4,
                },
                {
                    "name": "softmax_lastdim",
                    "make": make_softmax,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
                {
                    "name": "layer_norm",
                    "make": make_layer_norm,
                    "atol": 4e-4,
                    "rtol": 4e-4,
                },
            ],
            repeats=3,
            variants=2)

    def test_repeated_accuracy_conv_upsample_and_pointwise_matrix(self):
        def make_small_conv2d(variant):
            torch.manual_seed(1500 + variant)
            in_channels = 4 + variant * 2
            out_channels = 5 + variant * 3
            module_cpu = nn.Conv2d(
                in_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=True).eval()
            module_vulkan = nn.Conv2d(
                in_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=True).eval()
            module_vulkan.load_state_dict(module_cpu.state_dict())
            module_vulkan = module_vulkan.to("vulkan")
            x = torch.randn(1, in_channels, 13 + variant, 15 + variant)

            return module_cpu, module_vulkan, (x,)

        def make_bilinear_upsample(variant):
            torch.manual_seed(1600 + variant)
            x = torch.randn(1, 3 + variant, 8 + variant, 7 + variant)

            def fn(t):
                return F.interpolate(
                    t,
                    scale_factor=2,
                    mode="bilinear",
                    align_corners=False)

            return fn, fn, (x,)

        def make_dav2_pointwise_conv(variant):
            torch.manual_seed(1700 + variant)
            out_channels = 192 if variant == 0 else 384
            module_cpu = nn.Conv2d(
                384,
                out_channels,
                kernel_size=1,
                bias=True).eval()
            module_vulkan = nn.Conv2d(
                384,
                out_channels,
                kernel_size=1,
                bias=True).eval()
            module_vulkan.load_state_dict(module_cpu.state_dict())
            module_vulkan = module_vulkan.to("vulkan")
            x = torch.randn(1, 384, 30, 20)

            return module_cpu, module_vulkan, (x,)

        self._assert_repeated_vulkan_accuracy(
            [
                {
                    "name": "small_conv2d_3x3",
                    "make": make_small_conv2d,
                    "atol": 3e-3,
                    "rtol": 1e-3,
                },
                {
                    "name": "bilinear_upsample",
                    "make": make_bilinear_upsample,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
                {
                    "name": "dav2_decoder_pointwise_conv",
                    "make": make_dav2_pointwise_conv,
                    "atol": 1e-4,
                    "rtol": 1e-4,
                    "repeats": 2,
                    "variants": 2,
                },
            ],
            repeats=3,
            variants=2)

    def test_vulkan_conv2d_decoder_3x3_s2p1_uses_specialized_path(self):
        for width in (56, 57):
            torch.manual_seed(1750 + width)
            x_cpu = torch.randn(1, 384, 37, width)
            weight_cpu = torch.randn(384, 384, 3, 3)
            bias_cpu = torch.randn(384)

            expected = F.conv2d(
                x_cpu,
                weight_cpu,
                bias_cpu,
                stride=2,
                padding=1,
                dilation=1,
                groups=1)

            torch.ops.vulkan_prepack.reset_fallback_counters()
            torch.ops.vulkan_prepack.reset_conv_aggregate()
            actual = F.conv2d(
                x_cpu.to("vulkan"),
                weight_cpu.to("vulkan"),
                bias_cpu.to("vulkan"),
                stride=2,
                padding=1,
                dilation=1,
                groups=1).cpu()

            self._assert_outputs_close(expected, actual, atol=2e-2, rtol=2e-2)
            self.assertEqual(torch.ops.vulkan_prepack.cpu_fallback_count(), 0)
            aggregate = torch.ops.vulkan_prepack.conv_aggregate_snapshot()
            self.assertTrue(
                any("kernel=conv2d_buffer_float_3x3_s2p1" in row
                    for row in aggregate),
                msg="\n".join(aggregate))

    def test_repeated_accuracy_linear_algebra_and_attention_matrix(self):
        def make_mm(variant):
            torch.manual_seed(1800 + variant)
            a = torch.randn(4 + variant, 5 + variant)
            b = torch.randn(5 + variant, 3 + variant)

            return torch.mm, torch.mm, (a, b)

        def make_addmm_transposed_weight(variant):
            torch.manual_seed(1900 + variant)
            batch = 8 + variant * 4
            in_features = 16 + variant * 8
            out_features = 6 + variant * 2
            x = torch.randn(batch, in_features)
            weight = torch.randn(out_features, in_features)
            bias = torch.randn(out_features)

            def fn(b, a, w):
                return torch.addmm(b, a, w.t())

            return fn, fn, (bias, x, weight)

        def make_bmm_transposed_weight(variant):
            torch.manual_seed(2000 + variant)
            batch = 2 + variant
            m = 3 + variant
            k = 5 + variant
            n = 4 + variant
            a = torch.randn(batch, m, k)
            b = torch.randn(batch, n, k)

            def fn(lhs, rhs):
                return torch.bmm(lhs, rhs.transpose(1, 2))

            return fn, fn, (a, b)

        def make_baddbmm(variant):
            torch.manual_seed(2100 + variant)
            batch = 2 + variant
            m = 3 + variant
            k = 4 + variant
            n = 5 + variant
            bias = torch.randn(batch, m, n)
            a = torch.randn(batch, m, k)
            b = torch.randn(batch, k, n)

            return torch.baddbmm, torch.baddbmm, (bias, a, b)

        def make_sdpa_3d(variant):
            torch.manual_seed(2200 + variant)
            heads = 2 + variant
            q_tokens = 7 + variant * 2
            kv_tokens = 5 + variant * 2
            head_dim = 8 + variant * 4
            q = torch.randn(heads, q_tokens, head_dim)
            k = torch.randn(heads, kv_tokens, head_dim)
            v = torch.randn(heads, kv_tokens, head_dim)

            def fn(query, key, value):
                return F.scaled_dot_product_attention(query, key, value)

            return fn, fn, (q, k, v)

        def make_sdpa_4d(variant):
            torch.manual_seed(2300 + variant)
            batch = 1
            heads = 2 + variant
            tokens = 6 + variant * 2
            head_dim = 8 + variant * 4
            q = torch.randn(batch, heads, tokens, head_dim)
            k = torch.randn(batch, heads, tokens, head_dim)
            v = torch.randn(batch, heads, tokens, head_dim)

            def fn(query, key, value):
                return F.scaled_dot_product_attention(query, key, value)

            return fn, fn, (q, k, v)

        self._assert_repeated_vulkan_accuracy(
            [
                {
                    "name": "mm",
                    "make": make_mm,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
                {
                    "name": "addmm_transposed_weight",
                    "make": make_addmm_transposed_weight,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
                {
                    "name": "bmm_transposed_weight",
                    "make": make_bmm_transposed_weight,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
                {
                    "name": "baddbmm",
                    "make": make_baddbmm,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
                {
                    "name": "sdpa_3d",
                    "make": make_sdpa_3d,
                    "atol": 3e-4,
                    "rtol": 3e-4,
                },
                {
                    "name": "sdpa_4d",
                    "make": make_sdpa_4d,
                    "atol": 3e-4,
                    "rtol": 3e-4,
                },
            ],
            repeats=3,
            variants=2)

    def test_repeated_accuracy_shape_layout_and_copy_matrix(self):
        def make_permute_reshape_readback(variant):
            torch.manual_seed(2400 + variant)
            x = torch.randn(1, 2, 17 + variant, 8)

            def fn(t):
                return t.permute(0, 2, 1, 3).reshape(1, 17 + variant, 16)

            return fn, fn, (x,)

        def make_slice_cat_stack(variant):
            torch.manual_seed(2500 + variant)
            x = torch.randn(2, 9 + variant * 2, 6)
            y = torch.randn(2, 9 + variant * 2, 6)

            def fn(a, b):
                left = a[:, :1]
                middle = b[:, 2::2]
                right = a[:, -2:]
                cat = torch.cat([left, middle, right], dim=1)
                stack = torch.stack([cat, cat + 0.5], dim=0)
                return cat, stack

            return fn, fn, (x, y)

        def make_texture_readback_view(variant):
            torch.manual_seed(2600 + variant)
            x = torch.randn(1, 3 + variant, 9 + variant, 11 + variant)

            def fn(t):
                return t[:, :, 1:, 1::2]

            return fn, fn, (x,)

        def make_hwc_uint8_upload_view(variant):
            torch.manual_seed(2700 + variant)
            h = 11 + variant * 2
            w = 13 + variant * 2
            rgba = torch.randint(0, 256, (h, w, 4), dtype=torch.uint8)

            def fn(t):
                return t[:, :, :3]

            return fn, fn, (rgba,)

        self._assert_repeated_vulkan_accuracy(
            [
                {
                    "name": "permute_reshape_readback",
                    "make": make_permute_reshape_readback,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
                {
                    "name": "slice_cat_stack",
                    "make": make_slice_cat_stack,
                    "atol": 1e-4,
                    "rtol": 1e-4,
                },
                {
                    "name": "texture_readback_view",
                    "make": make_texture_readback_view,
                    "atol": 1e-4,
                    "rtol": 1e-4,
                },
                {
                    "name": "hwc_uint8_upload_view",
                    "make": make_hwc_uint8_upload_view,
                },
            ],
            repeats=3,
            variants=2)

    def test_repeated_accuracy_pooling_and_norm_matrix(self):
        def make_avg_pool2d(variant):
            torch.manual_seed(2800 + variant)
            x = torch.randn(2, 3 + variant, 8 + variant * 2, 10 + variant * 2)

            def fn(t):
                return F.avg_pool2d(t, kernel_size=2, stride=2)

            return fn, fn, (x,)

        def make_max_pool2d(variant):
            torch.manual_seed(2900 + variant)
            x = torch.randn(2, 3 + variant, 8 + variant * 2, 10 + variant * 2)

            def fn(t):
                return F.max_pool2d(t, kernel_size=2, stride=2)

            return fn, fn, (x,)

        def make_adaptive_avg_pool2d(variant):
            torch.manual_seed(3000 + variant)
            x = torch.randn(2, 3 + variant, 8 + variant * 2, 10 + variant * 2)

            def fn(t):
                return F.adaptive_avg_pool2d(t, (1 + variant, 2))

            return fn, fn, (x,)

        def make_batch_norm_eval(variant):
            torch.manual_seed(3100 + variant)
            channels = 4 + variant * 2
            module_cpu = nn.BatchNorm2d(channels).eval()
            module_vulkan = nn.BatchNorm2d(channels).eval()
            module_vulkan.load_state_dict(module_cpu.state_dict())
            module_vulkan = module_vulkan.to("vulkan")
            x = torch.randn(2, channels, 9 + variant, 7 + variant)

            return module_cpu, module_vulkan, (x,)

        def make_group_norm(variant):
            torch.manual_seed(3200 + variant)
            groups = 2 + variant
            channels = groups * 4
            module_cpu = nn.GroupNorm(groups, channels).eval()
            module_vulkan = nn.GroupNorm(groups, channels).eval()
            module_vulkan.load_state_dict(module_cpu.state_dict())
            module_vulkan = module_vulkan.to("vulkan")
            x = torch.randn(2, channels, 5 + variant, 7 + variant)

            return module_cpu, module_vulkan, (x,)

        def make_rms_norm(variant):
            torch.manual_seed(3300 + variant)
            normalized_shape = 8 + variant * 4
            x = torch.randn(2, 4 + variant, normalized_shape)
            weight = torch.randn(normalized_shape)

            def fn(t, w):
                return F.rms_norm(t, (normalized_shape,), w, 1e-5)

            return fn, fn, (x, weight)

        self._assert_repeated_vulkan_accuracy(
            [
                {
                    "name": "avg_pool2d",
                    "make": make_avg_pool2d,
                },
                {
                    "name": "max_pool2d",
                    "make": make_max_pool2d,
                },
                {
                    "name": "adaptive_avg_pool2d",
                    "make": make_adaptive_avg_pool2d,
                    "atol": 5e-4,
                    "rtol": 5e-3,
                },
                {
                    "name": "batch_norm_eval",
                    "make": make_batch_norm_eval,
                    "atol": 2e-4,
                    "rtol": 2e-4,
                },
                {
                    "name": "group_norm",
                    "make": make_group_norm,
                    "atol": 3e-4,
                    "rtol": 3e-4,
                },
                {
                    "name": "rms_norm",
                    "make": make_rms_norm,
                    "atol": 3e-4,
                    "rtol": 3e-4,
                },
            ],
            repeats=3,
            variants=2)

    def _make_depth_anything_style_features(
            self,
            *,
            patch_h=4,
            patch_w=4,
            embed_dim=16,
            use_clstoken=False):
        batch_size = 1
        token_count = patch_h * patch_w
        features = []
        for _ in range(4):
            tokens = torch.randn(batch_size, token_count, embed_dim)
            if use_clstoken:
                cls_token = torch.randn(batch_size, embed_dim)
                features.append((tokens, cls_token))
            else:
                features.append((tokens,))
        return features

    def _create_conv2d_context_from_module(self, conv):
        bias = None if conv.bias is None else conv.bias.detach().to(torch.float32).contiguous()
        return torch.ops.vulkan_prepack.create_conv2d_context(
            conv.weight.detach().to(torch.float32).contiguous(),
            bias,
            list(conv.stride),
            list(conv.padding),
            list(conv.dilation),
            conv.groups,
        )

    def _create_tconv2d_context_from_module(self, conv):
        bias = None if conv.bias is None else conv.bias.detach().to(torch.float32).contiguous()
        return torch.ops.vulkan_prepack.create_tconv2d_context(
            conv.weight.detach().to(torch.float32).contiguous(),
            bias,
            list(conv.stride),
            list(conv.padding),
            list(conv.output_padding),
            list(conv.dilation),
            conv.groups,
        )

    def _create_vision_decoder_fusion_block_context_from_module(self, block, label):
        return torch.ops.vulkan_prepack.create_vision_decoder_fusion_block_context(
            block.residual_1.conv1.weight.detach().to(torch.float32).contiguous(),
            block.residual_1.conv1.bias.detach().to(torch.float32).contiguous(),
            block.residual_1.conv2.weight.detach().to(torch.float32).contiguous(),
            block.residual_1.conv2.bias.detach().to(torch.float32).contiguous(),
            block.residual_2.conv1.weight.detach().to(torch.float32).contiguous(),
            block.residual_2.conv1.bias.detach().to(torch.float32).contiguous(),
            block.residual_2.conv2.weight.detach().to(torch.float32).contiguous(),
            block.residual_2.conv2.bias.detach().to(torch.float32).contiguous(),
            block.out_conv.weight.detach().to(torch.float32).contiguous(),
            block.out_conv.bias.detach().to(torch.float32).contiguous(),
            True,
            label,
        )

    def _create_depth_anything_style_dpt_decoder_context(self, module, label):
        head_context = torch.ops.vulkan_prepack.create_vision_decoder_head_context(
            torch.zeros(1, dtype=torch.float32),
            self._create_vision_decoder_fusion_block_context_from_module(
                module.refinenet4, f"{label}.refinenet4"
            ),
            self._create_vision_decoder_fusion_block_context_from_module(
                module.refinenet3, f"{label}.refinenet3"
            ),
            self._create_vision_decoder_fusion_block_context_from_module(
                module.refinenet2, f"{label}.refinenet2"
            ),
            self._create_vision_decoder_fusion_block_context_from_module(
                module.refinenet1, f"{label}.refinenet1"
            ),
            self._create_conv2d_context_from_module(module.output_conv1),
            self._create_conv2d_context_from_module(module.output_conv2[0]),
            self._create_conv2d_context_from_module(module.output_conv2[2]),
            True,
            f"{label}.head",
        )
        return torch.ops.vulkan_prepack.create_vision_decoder_preprocess_head_context(
            torch.zeros(1, dtype=torch.float32),
            self._create_conv2d_context_from_module(module.projects[0]),
            self._create_conv2d_context_from_module(module.projects[1]),
            self._create_conv2d_context_from_module(module.projects[2]),
            self._create_conv2d_context_from_module(module.projects[3]),
            self._create_tconv2d_context_from_module(module.resize_layers[0]),
            self._create_tconv2d_context_from_module(module.resize_layers[1]),
            self._create_conv2d_context_from_module(module.resize_layers[3]),
            self._create_conv2d_context_from_module(module.scratch_layers[0]),
            self._create_conv2d_context_from_module(module.scratch_layers[1]),
            self._create_conv2d_context_from_module(module.scratch_layers[2]),
            self._create_conv2d_context_from_module(module.scratch_layers[3]),
            head_context,
            label,
        )

