    def _run_depth_anything_v2_supported_reference(self, tokens, fixture):
        captured = torch.ops.vulkan_prepack.run_vision_backbone_stack_norm_replay_bundle_bridge(
            tokens,
            fixture["contexts"],
            fixture["capture_indices"],
            [fixture["embed_dim"]],
            fixture["norm_context"],
        )
        patch_tokens = []
        for tensor in captured:
            if tensor.dim() == 2:
                patch_tokens.append(tensor[1:, :])
            else:
                patch_tokens.append(tensor[:, 1:, :])
        return torch.ops.vulkan_prepack.run_vision_decoder_preprocess_head_context(
            patch_tokens[0],
            patch_tokens[1],
            patch_tokens[2],
            patch_tokens[3],
            fixture["patch_h"],
            fixture["patch_w"],
            fixture["output_size"],
            fixture["preprocess_context"],
        )

    def _make_depth_anything_v2_tokens_from_image_fixture(self, image, fixture):
        feature_map = torch.ops.vulkan_prepack.run_conv2d_context(
            image,
            fixture["patch_embed_context"],
        )
        tokens = torch.ops.vulkan_prepack.feature_map_to_tokens(feature_map)
        tokens = torch.cat(
            (
                fixture["prefix_token"].expand(tokens.shape[0], -1, -1),
                tokens + fixture["patch_pos_encoding"],
            ),
            dim=1,
        )
        if tokens.shape[0] == 1:
            tokens = tokens.reshape(tokens.shape[1], tokens.shape[2])
        return tokens

    def _run_repo_python_subprocess(
            self,
            script,
            *,
            extra_env=None,
            extra_python_paths=None,
            timeout=120,
            error_prefix="Vulkan subprocess failed."):
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        env = os.environ.copy()
        existing_pythonpath = env.get("PYTHONPATH")
        pythonpath_entries = [repo_root]
        if extra_python_paths:
            pythonpath_entries.extend(extra_python_paths)
        if existing_pythonpath:
            pythonpath_entries.append(existing_pythonpath)
        env["PYTHONPATH"] = os.pathsep.join(pythonpath_entries)
        if sys.platform == "win32":
            existing_path = env.get("PATH")
            path_entries = existing_path.split(os.pathsep) if existing_path else []
            local_dll_dirs = [
                path for path in (LOCAL_TORCH_LIB_DIR, LOCAL_BUILD_BIN_DIR)
                if os.path.isdir(path) and path not in path_entries
            ]
            if local_dll_dirs:
                env["PATH"] = os.pathsep.join(local_dll_dirs + path_entries)
        if extra_env:
            env.update(extra_env)

        script = textwrap.dedent(script)
        bootstrap_paths = [repo_root]
        if extra_python_paths:
            bootstrap_paths.extend(extra_python_paths)
        bootstrap = "".join(
            f"sys.path.insert(0, {path!r})\n"
            for path in reversed(bootstrap_paths)
        )
        script = "import sys\n" + bootstrap + script
        if sys.platform == "win32":
            dll_bootstrap = "".join(
                f"os.add_dll_directory({path!r})\n"
                for path in (LOCAL_TORCH_LIB_DIR, LOCAL_BUILD_BIN_DIR)
                if os.path.isdir(path)
            )
            script = (
                "import ctypes\nimport os\n"
                "ctypes.windll.kernel32.SetErrorMode(0x0001 | 0x0002 | 0x8000)\n"
                + dll_bootstrap
                + script
            )

        result = subprocess.run(
            [sys.executable, "-c", script],
            env=env,
            cwd=repo_root,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        self.assertEqual(
            result.returncode,
            0,
            msg=(
                f"{error_prefix}\n"
                f"stdout:\n{result.stdout}\n"
                f"stderr:\n{result.stderr}"
            ),
        )
        return repo_root, result

    def _skip_if_repo_subprocess_cannot_import(
            self,
            module_name,
            *,
            extra_python_paths=None):
        try:
            self._run_repo_python_subprocess(
                f"import {module_name}\n",
                extra_python_paths=extra_python_paths,
                timeout=30,
                error_prefix=(
                    f"Optional dependency probe for {module_name} failed."
                ),
            )
        except (AssertionError, subprocess.TimeoutExpired):
            self.skipTest(f"{module_name} is not importable in the repo subprocess")

    def _assert_vision_runtime_policy_log(
            self,
            log_text,
            *,
            execution_phase,
            program_kind):
        self.assertRegex(
            log_text,
            rf"runtime_policy workload=\w+ source_workload=\w+ model_domain=Vision execution_phase={execution_phase} .* backend_route=Vulkan .* has_execution_program_plan=1 execution_program_kind={program_kind} .* has_boundary_plan=0")

    def _benchmarks_python_path(self):
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        return os.path.join(os.path.dirname(repo_root), "scripts", "benchmarks")

    def test_vulkan_device_api_reports_properties(self):
        device_count = torch.vulkan.device_count()
        self.assertGreaterEqual(device_count, 1)

        current_device = torch.vulkan.current_device()
        self.assertGreaterEqual(current_device, 0)
        self.assertLess(current_device, device_count)

        current_properties = torch.vulkan.get_device_properties()
        self.assertEqual(current_properties.index, current_device)
        self.assertEqual(
            torch.vulkan.get_device_name(current_device),
            current_properties.name)

        valid_device_types = {
            "other",
            "integrated_gpu",
            "discrete_gpu",
            "virtual_gpu",
            "cpu",
            "unknown",
        }

        for device_index in range(device_count):
            with self.subTest(device_index=device_index):
                properties = torch.vulkan.get_device_properties(device_index)
                self.assertEqual(properties.index, device_index)
                self.assertEqual(
                    torch.vulkan.get_device_name(device_index),
                    properties.name)
                self.assertTrue(properties.name)
                self.assertIn(properties.type, valid_device_types)
                self.assertGreater(properties.api_version_raw, 0)
                self.assertGreaterEqual(properties.num_compute_queues, 1)
                self.assertGreater(properties.max_image_dimension_2d, 0)
                self.assertGreater(properties.max_image_dimension_3d, 0)
                self.assertIn(properties.name, repr(properties))

    def test_vulkan_set_device_and_context_manager_select_default_device(self):
        previous_device = torch.vulkan.current_device()
        target_device = (
            self._non_default_working_vulkan_device_index()
            if len(self._working_vulkan_device_indices()) > 1
            else 0
        )

        try:
            torch.vulkan.set_device(target_device)
            self.assertEqual(torch.vulkan.current_device(), target_device)

            default_tensor = torch.empty((2, 3), device="vulkan")
            self.assertEqual(default_tensor.device, self._vulkan_device(target_device))

            with torch.vulkan.device(previous_device):
                self.assertEqual(torch.vulkan.current_device(), previous_device)
                nested_tensor = torch.ones((2, 3), device="vulkan")
                self.assertEqual(nested_tensor.device, self._vulkan_device(previous_device))

            self.assertEqual(torch.vulkan.current_device(), target_device)
        finally:
            torch.vulkan.set_device(previous_device)

        self.assertEqual(torch.vulkan.current_device(), previous_device)

    def test_vulkan_explicit_device_index_allocation_and_to(self):
        with torch.inference_mode():
            cpu = torch.randn(2, 3, 4)

            tensor_vulkan0 = cpu.to("vulkan:0")
            empty_vulkan0 = torch.empty(cpu.shape, device="vulkan:0")

            self.assertEqual(tensor_vulkan0.device, self._vulkan_device(0))
            self.assertEqual(empty_vulkan0.device, self._vulkan_device(0))
            self._assert_outputs_close(cpu, tensor_vulkan0.cpu())

            converted = self._to_vulkan((cpu, [cpu]), device=self._vulkan_device(0))
            self.assertEqual(converted[0].device, self._vulkan_device(0))
            self.assertEqual(converted[1][0].device, self._vulkan_device(0))

            if len(self._working_vulkan_device_indices()) > 1:
                target_device = self._vulkan_device(
                    self._non_default_working_vulkan_device_index())
                tensor_vulkan_other = cpu.to(target_device)
                self.assertEqual(tensor_vulkan_other.device, target_device)
                self._assert_outputs_close(cpu, tensor_vulkan_other.cpu())

    def test_vulkan_module_to_explicit_device(self):
        target_device = self._vulkan_device(
            self._non_default_working_vulkan_device_index()
            if len(self._working_vulkan_device_indices()) > 1
            else 0
        )

        torch.manual_seed(0)
        module_cpu = nn.Linear(4, 3).eval()
        module_vulkan = nn.Linear(4, 3).eval()
        module_vulkan.load_state_dict(module_cpu.state_dict())
        module_vulkan = module_vulkan.to(target_device)

        for name, parameter in module_vulkan.named_parameters():
            self.assertEqual(
                parameter.device,
                target_device,
                msg=f"Parameter '{name}' was not moved to {target_device}")
        for name, buffer in module_vulkan.named_buffers():
            self.assertEqual(
                buffer.device,
                target_device,
                msg=f"Buffer '{name}' was not moved to {target_device}")

        x_cpu = torch.randn(2, 4)
        x_vulkan = x_cpu.to(target_device)
        with torch.inference_mode():
            expected = module_cpu(x_cpu)
            actual = module_vulkan(x_vulkan).cpu()

        self._assert_outputs_close(expected, actual, atol=1e-4, rtol=1e-4)

    def test_vulkan_cross_device_copy_rejected(self):
        self._require_multiple_vulkan_devices()
        source_device = 0
        target_device = next(
            device_index
            for device_index in range(torch.vulkan.device_count())
            if device_index != source_device
        )

        with torch.inference_mode():
            src = torch.randn(2, 3, 4).to(self._vulkan_device(source_device))
            dst = torch.empty((2, 3, 4), device=self._vulkan_device(target_device))

            self.assertEqual(src.device, self._vulkan_device(source_device))
            self.assertEqual(dst.device, self._vulkan_device(target_device))

            with self.assertRaisesRegex(
                    RuntimeError,
                    "Cross-device Vulkan copy is not supported yet"):
                dst.copy_(src)

    def test_vulkan_device_group_and_mesh_api(self):
        device_indices = self._working_vulkan_device_group()

        group = torch.vulkan.device_group(device_indices)
        mesh = torch.vulkan.device_mesh(device_indices)

        self.assertEqual(group.indices, tuple(device_indices))
        self.assertEqual(len(group.devices), len(device_indices))
        self.assertEqual(group.names, tuple(
            torch.vulkan.get_device_name(device_index)
            for device_index in device_indices))
        self.assertIn("DeviceGroup", repr(group))

        self.assertEqual(mesh.device_type, "vulkan")
        self.assertEqual(mesh.ndim, 1)
        self.assertEqual(mesh.shape, (len(device_indices),))
        self.assertEqual(mesh.indices, tuple(device_indices))
        self.assertIn("DeviceMesh", repr(mesh))

        with self.assertRaisesRegex(
                ValueError,
                "Duplicate Vulkan devices are not allowed"):
            torch.vulkan.device_group([device_indices[0], device_indices[0]])

    def test_vulkan_replicate_module_matches_cpu(self):
        device_indices = self._linear_capable_vulkan_device_group(min_devices=1)
        device_group = torch.vulkan.device_group(device_indices)

        torch.manual_seed(0)
        module = nn.Linear(4, 3).eval()
        runner = torch.vulkan.replicate_module(module, device_group)

        x = torch.randn(12, 4)
        with torch.inference_mode():
            expected = module(x)
            actual = runner(x)

        self.assertEqual(actual.device.type, "cpu")
        self._assert_outputs_close(expected, actual, atol=1e-4, rtol=1e-4)

    def test_vulkan_parallelize_module_replicate_style_matches_cpu(self):
        device_indices = self._linear_capable_vulkan_device_group(min_devices=1)
        mesh = torch.vulkan.device_mesh(device_indices)

        torch.manual_seed(0)
        module = nn.Linear(4, 3).eval()
        parallelized = torch.vulkan.parallelize_module(
            module,
            mesh,
            torch.vulkan.Replicate(),
        )

        x = torch.randn(10, 4)
        with torch.inference_mode():
            expected = module(x)
            actual = parallelized(x)

        self.assertEqual(actual.device.type, "cpu")
        self._assert_outputs_close(expected, actual, atol=1e-4, rtol=1e-4)

    def test_vulkan_parallelize_module_colwise_and_rowwise_match_cpu(self):
        device_indices = self._linear_capable_vulkan_device_group(min_devices=1)
        mesh = torch.vulkan.device_mesh(device_indices)

        class ToyMlp(nn.Module):
            def __init__(self) -> None:
                super().__init__()
                self.in_proj = nn.Linear(6, 10)
                self.activation = nn.ReLU()
                self.out_proj = nn.Linear(10, 4)

            def forward(self, x):
                return self.out_proj(self.activation(self.in_proj(x)))

        torch.manual_seed(0)
        module = ToyMlp().eval()
        parallelized = torch.vulkan.parallelize_module(
            module,
            mesh,
            {
                "in_proj": torch.vulkan.ColwiseParallel(),
                "out_proj": torch.vulkan.RowwiseParallel(),
            },
        )

        x = torch.randn(11, 6)
        with torch.inference_mode():
            expected = module(x)
            actual = parallelized(x)

        self.assertEqual(actual.device.type, "cpu")
        self._assert_outputs_close(expected, actual, atol=1e-4, rtol=1e-4)

    def test_vulkan_replicate_module_multi_device_matches_cpu_in_subprocess(self):
        script = """
            import sys
            import torch
            import torch.nn as nn

            capable = []
            torch.manual_seed(0)
            with torch.inference_mode():
                for device_index in range(torch.vulkan.device_count()):
                    try:
                        device = torch.device("vulkan", device_index)
                        module = nn.Linear(4, 3).eval().to(device)
                        sample = torch.randn(2, 4).to(device)
                        module(sample).cpu()
                    except RuntimeError:
                        continue
                    capable.append(device_index)

            if len(capable) < 2:
                print("SKIP: fewer than 2 linear-capable Vulkan devices")
                sys.exit(0)

            torch.manual_seed(0)
            module = nn.Linear(4, 3).eval()
            try:
                torch.vulkan.replicate_module(module, capable[:2])
            except RuntimeError as exc:
                if "multi-device replicate_module is disabled" not in str(exc):
                    raise
            else:
                raise AssertionError(
                    "multi-device replicate_module should hard-fail until "
                    "cross-device lifetime is stable"
                )
            print("OK")
        """

        _, result = self._run_repo_python_subprocess(
            script,
            error_prefix=(
                "Vulkan multi-device replicate_module subprocess validation failed."
            ),
        )
        if "SKIP:" in result.stdout:
            self.skipTest(result.stdout.strip())
        self.assertIn("OK", result.stdout)

    def test_binary_and_unary_ops(self):
        torch.manual_seed(0)
        x = torch.randn(2, 3, 8, 8)
        positive = torch.rand(2, 3, 8, 8)

        cases = [
            ("add_tensor", lambda t: t + t, (x,)),
            ("sub_scalar", lambda t: t - 0.25, (x,)),
            ("mul_tensor", lambda t: t * t, (x,)),
            ("div_scalar", lambda t: t / 2.0, (x,)),
            ("fill_scalar", lambda t: t.clone().fill_(0.25), (x,)),
            ("relu", F.relu, (x,)),
            ("hardtanh", lambda t: F.hardtanh(t, -0.5, 0.5), (x,)),
            ("sigmoid", torch.sigmoid, (x,)),
            ("softplus_default", F.softplus, (x,)),
            ("softplus_custom", lambda t: F.softplus(t, beta=0.75, threshold=10.0), (x,)),
            ("silu", F.silu, (x,)),
            ("exp", torch.exp, (x,)),
            ("sin", torch.sin, (x,)),
            ("cos", torch.cos, (x,)),
            ("neg", torch.neg, (x,)),
            ("sqrt", lambda t: torch.sqrt(t + 1e-3), (positive,)),
            ("rsqrt", lambda t: torch.rsqrt(t + 1e-3), (positive,)),
            ("clamp", lambda t: torch.clamp(t, -0.2, 0.3), (x,)),
        ]

        for name, fn, args in cases:
            with self.subTest(case=name):
                self._assert_vulkan_matches_cpu(fn, *args)

        with self.subTest(case="gelu_default"):
            self._assert_vulkan_matches_cpu(
                lambda t: F.gelu(t),
                x,
                atol=1e-3,
                rtol=1e-3)

    def test_large_buffer_backed_binary_and_unary_ops(self):
        torch.manual_seed(0)
        x = torch.randn(2048, 1024)
        y = torch.randn(2048, 1024)

        with torch.inference_mode():
            x_vulkan = x.to("vulkan")
            y_vulkan = y.to("vulkan")

            self._assert_outputs_close(
                torch.exp(x),
                torch.exp(x_vulkan).cpu(),
                atol=1e-4,
                rtol=1e-4)
            self._assert_outputs_close(
                F.silu(x),
                F.silu(x_vulkan).cpu(),
                atol=1e-4,
                rtol=1e-4)
            self._assert_outputs_close(
                x + y,
                (x_vulkan + y_vulkan).cpu(),
                atol=1e-4,
                rtol=1e-4)
            self._assert_outputs_close(
                x * y,
                (x_vulkan * y_vulkan).cpu(),
                atol=1e-4,
                rtol=1e-4)

    def test_pow_integer_scalar_negative_base(self):
        small = torch.linspace(-2.0, 2.0, steps=48, dtype=torch.float32).reshape(2, 3, 8)
        large = torch.linspace(-2.0, 2.0, steps=1025 * 1027, dtype=torch.float32).reshape(1025, 1027)

        with torch.inference_mode():
            for exponent in (2, 3, 4):
                with self.subTest(exponent=exponent, layout="texture_like"):
                    expected = small.pow(exponent)
                    actual = small.to("vulkan").pow(exponent).cpu()
                    self._assert_outputs_close(
                        expected,
                        actual,
                        atol=1e-4,
                        rtol=1e-4,
                    )

                    expected_inplace = small.clone()
                    expected_inplace.pow_(exponent)
                    actual_inplace = small.to("vulkan")
                    actual_inplace.pow_(exponent)
                    self._assert_outputs_close(
                        expected_inplace,
                        actual_inplace.cpu(),
                        atol=1e-4,
                        rtol=1e-4,
                    )

                with self.subTest(exponent=exponent, layout="buffer_like"):
                    expected = large.pow(exponent)
                    actual = large.to("vulkan").pow(exponent).cpu()
                    self._assert_outputs_close(
                        expected,
                        actual,
                        atol=1e-4,
                        rtol=1e-4,
                    )

