    def test_grid_sampler_2d_unsupported_mode_uses_recorded_fallback(self):
        torch.ops.vulkan_prepack.reset_fallback_counters()
        input_cpu = torch.arange(1 * 1 * 3 * 3, dtype=torch.float32).reshape(
            1, 1, 3, 3)
