    def test_bfloat16_buffer_full_reductions(self):
        torch.manual_seed(0)
        x = torch.randn(513, 257, dtype=torch.bfloat16)
        x_vulkan = x.to("vulkan")

        with torch.inference_mode():
            expected_sum = self._single_threaded_cpu(
                lambda: torch.sum(x, dtype=torch.float32))
            actual_sum = torch.sum(x_vulkan, dtype=torch.float32).cpu()
            expected_mean = self._single_threaded_cpu(
                lambda: torch.mean(x, dtype=torch.float32))
            actual_mean = torch.mean(x_vulkan, dtype=torch.float32).cpu()

        self.assertEqual(actual_sum.dtype, torch.float32)
        self.assertEqual(actual_mean.dtype, torch.float32)
        self._assert_outputs_close(expected_sum, actual_sum, atol=1e-4, rtol=1e-4)
        self._assert_outputs_close(expected_mean, actual_mean, atol=1e-4, rtol=1e-4)

    def test_int32_buffer_binary_tensor_ops(self):
        torch.manual_seed(0)
        x = torch.randint(-16, 16, (513, 257), dtype=torch.int32)
        y = torch.randint(-8, 8, (513, 257), dtype=torch.int32)
        x_vulkan = x.to("vulkan")
        y_vulkan = y.to("vulkan")

        with torch.inference_mode():
            self._assert_outputs_close(x + y, (x_vulkan + y_vulkan).cpu())
            self._assert_outputs_close(x - y, (x_vulkan - y_vulkan).cpu())
            self._assert_outputs_close(x * y, (x_vulkan * y_vulkan).cpu())

    def test_float_buffer_binary_broadcast_ops(self):
        torch.manual_seed(0)
        x = torch.randn(1, 17, 384, dtype=torch.float32)
        weight = torch.randn(384, 384, dtype=torch.float32)
        bias = torch.randn(384, dtype=torch.float32)
        gamma = torch.randn(384, dtype=torch.float32)

        with torch.inference_mode():
            expected_linear = F.linear(x, weight, bias)
            expected_mul = expected_linear * gamma
            expected_add = expected_linear + gamma

            previous = torch.ops.vulkan_prepack.swap_runtime_label(
                "depth.dino.backbone.block"
            )
            x_vulkan = x.to("vulkan")
            weight_vulkan = weight.to("vulkan")
            bias_vulkan = bias.to("vulkan")
            gamma_vulkan = gamma.to("vulkan")
            try:
                actual_linear = F.linear(x_vulkan, weight_vulkan, bias_vulkan)
                actual_mul = (actual_linear * gamma_vulkan).cpu()
                actual_add = (actual_linear + gamma_vulkan).cpu()
            finally:
                torch.ops.vulkan_prepack.swap_runtime_label(previous)

        self._assert_outputs_close(expected_mul, actual_mul, atol=1e-4, rtol=1e-4)
        self._assert_outputs_close(expected_add, actual_add, atol=1e-4, rtol=1e-4)

    def test_elementwise_broadcast_contract_generated_float_buffer_spec(self):
        spec = _load_vulkan_contract_spec("elementwise_broadcast_contract.json")
        op_hit_log_name = contract_spec_utils.contract_log_name(
            spec,
            {"name": "generated"},
            "op_hit_test.log",
        )
        admission_log_name = contract_spec_utils.contract_log_name(
            spec,
            {"name": "generated"},
            "contract_admission.jsonl",
        )
        value_trace_log_names = [
            contract_spec_utils.contract_log_name(
                spec,
                case,
                "value_trace.jsonl",
            )
            for _, case, _ in (
                contract_spec_utils.iter_shape_envelope_contract_cases(spec)
            )
        ]
        log_paths = [
            os.path.join(REPO_ROOT, op_hit_log_name),
            os.path.join(REPO_ROOT, admission_log_name),
        ]
        log_paths.extend(os.path.join(REPO_ROOT, name) for name in value_trace_log_names)
        for path in log_paths:
            if os.path.exists(path):
                os.remove(path)

        try:
            script = """
                import json
                import os
                import re
                import sys
                import torch
                import torch.nn.functional as F
                sys.path.insert(
                    0,
                    os.path.join(os.getcwd(), "test", "vulkan_contract_specs"),
                )
                import contract_spec_utils

                spec_path = os.path.join(
                    os.getcwd(),
                    "test",
                    "vulkan_contract_specs",
                    "elementwise_broadcast_contract.json",
                )
                with open(spec_path, encoding="utf-8") as handle:
                    spec = json.load(handle)

                op_hit_log = os.environ["PYTORCH_VULKAN_OP_HIT_LOG"]
                admission_log = os.environ[
                    "PYTORCH_VULKAN_CONTRACT_ADMISSION_LOG"
                ]
                route_hit = "op=" + spec["route_label"]

                def dtype_for_case(case):
                    return {
                        "float32": torch.float32,
                        "int32": torch.int32,
                    }[case["dtype"]]

                def read_file(path):
                    if not os.path.exists(path):
                        return ""
                    with open(path, encoding="utf-8") as handle:
                        return handle.read()

                def read_value_trace(log_path):
                    if not os.path.exists(log_path):
                        return []
                    with open(log_path, encoding="utf-8") as log_file:
                        return [
                            json.loads(line)
                            for line in log_file
                            if line.strip()
                        ]

                def read_admission_log():
                    if not os.path.exists(admission_log):
                        return []
                    with open(admission_log, encoding="utf-8") as log_file:
                        return [
                            json.loads(line)
                            for line in log_file
                            if line.strip()
                        ]

                def assert_admission_event(case, expected):
                    records = read_admission_log()
                    assert len(records) == 1, (case, records)
                    record = records[0]
                    assert record.get("event") == "vulkan_contract_admission", (
                        case,
                        record,
                    )
                    for key in ("contract_name", "family_name", "tuple_id"):
                        expected_value = {
                            "contract_name": spec["contract_name"],
                            "family_name": spec["family"],
                            "tuple_id": spec["tuple_id"],
                        }[key]
                        assert record.get(key) == expected_value, (
                            case,
                            key,
                            expected_value,
                            record,
                        )
                    for key, value in expected.items():
                        assert record.get(key) == value, (
                            case,
                            key,
                            value,
                            record,
                        )

                def value_trace_provenance(log_path):
                    trace_records = read_value_trace(log_path)
                    return trace_records, "\\n".join(
                        str(record.get("output_provenance", ""))
                        for record in trace_records
                    )

                def apply_op(left, right, op):
                    if op == "add":
                        return left + right
                    if op == "mul":
                        return left * right
                    if op == "sub":
                        return left - right
                    if op == "div":
                        return left / right
                    raise AssertionError("unsupported test op " + op)

                def make_float_buffer_operand(shape, seed):
                    torch.manual_seed(seed)
                    source = torch.randn(*shape, dtype=torch.float32)
                    last_dim = shape[-1]
                    weight = torch.randn(last_dim, last_dim, dtype=torch.float32)
                    bias = torch.randn(last_dim, dtype=torch.float32)
                    expected = F.linear(source, weight, bias)
                    actual = F.linear(
                        source.to("vulkan"),
                        weight.to("vulkan"),
                        bias.to("vulkan"),
                    )
                    return expected, actual

                def make_direct_operand(shape, dtype, seed):
                    torch.manual_seed(seed)
                    if dtype == torch.float32:
                        cpu = torch.randn(*shape, dtype=dtype)
                    else:
                        cpu = torch.randint(-8, 8, shape, dtype=dtype)
                    return cpu, cpu.to("vulkan")

                def run_case(case, expect_native_route):
                    log_name = contract_spec_utils.contract_log_name(
                        spec,
                        case,
                        "value_trace.jsonl",
                    )
                    log_path = os.path.join(os.getcwd(), log_name)
                    for path in (op_hit_log, log_path, admission_log):
                        if os.path.exists(path):
                            os.remove(path)
                    os.environ["PYTORCH_VULKAN_VALIDATE_VALUES"] = "1"
                    os.environ["PYTORCH_VULKAN_VALUE_TRACE_LOG"] = log_path
                    os.environ["PYTORCH_VULKAN_VALUE_TRACE_SAMPLES"] = "1"

                    dtype = dtype_for_case(case)
                    expected_error = case.get("expected_error_regex")
                    torch.ops.vulkan_prepack.reset_fallback_counters()
                    if expect_native_route:
                        self_cpu, self_vulkan = make_float_buffer_operand(
                            case["self_shape"],
                            7000 + len(case["name"]),
                        )
                    else:
                        self_cpu, self_vulkan = make_direct_operand(
                            case["self_shape"],
                            dtype,
                            7100 + len(case["name"]),
                        )
                    other_cpu, other_vulkan = make_direct_operand(
                        case["other_shape"],
                        dtype,
                        7200 + len(case["name"]),
                    )
                    if os.path.exists(admission_log):
                        os.remove(admission_log)

                    if expected_error is not None:
                        try:
                            apply_op(self_vulkan, other_vulkan, case["op"])
                        except RuntimeError as error:
                            assert re.search(expected_error, str(error)), (
                                case,
                                str(error),
                            )
                        else:
                            raise AssertionError((case, "expected RuntimeError"))
                        assert route_hit not in read_file(op_hit_log), (
                            case,
                            read_file(op_hit_log),
                        )
                        return

                    expected = apply_op(self_cpu, other_cpu, case["op"])
                    actual_vulkan = apply_op(self_vulkan, other_vulkan, case["op"])
                    actual = actual_vulkan.cpu()
                    torch.testing.assert_close(actual, expected, atol=1e-4, rtol=1e-4)

                    fallback_count = torch.ops.vulkan_prepack.cpu_fallback_count()
                    readback_count = torch.ops.vulkan_prepack.sync_readback_count()
                    op_hit_text = read_file(op_hit_log)
                    trace_records, provenance = value_trace_provenance(log_path)
                    if expect_native_route:
                        assert fallback_count == 0, (
                            case,
                            fallback_count,
                            op_hit_text,
                        )
                        assert route_hit in op_hit_text, (case, op_hit_text)
                        expected_route = (
                            "route="
                            + case["expected_tensor_provenance_route"]
                        )
                        assert expected_route in provenance, (
                            case,
                            provenance,
                            trace_records,
                        )
                        for expected in (
                            "contract_name=" + spec["contract_name"],
                            "contract_family=" + spec["family"],
                            "contract_tuple_id=" + spec["tuple_id"],
                            "contract_materialization_policy="
                            + spec["metadata"]["materialization_policy"],
                        ):
                            assert expected in provenance, (
                                case,
                                expected,
                                provenance,
                                trace_records,
                            )
                        assert_admission_event(case, {
                            "outcome": "accept",
                            "phase": "admitted",
                            "predicate": "match_elementwise_broadcast_contract",
                            "reason_code": "matched",
                            "source": "handwritten",
                        })
                        if not case["expected_sync_readback"]:
                            assert readback_count == 0, (
                                case,
                                readback_count,
                                trace_records,
                            )
                    else:
                        assert route_hit not in op_hit_text, (case, op_hit_text)
                        if contract_spec_utils.expected_negative_flag(
                            case,
                            "expected_cpu_fallback",
                        ):
                            assert fallback_count == 1, (
                                case,
                                fallback_count,
                                op_hit_text,
                            )

                def run_attribute_reject_case():
                    case = {"name": "unsupported_div_attribute_mismatch"}
                    for path in (op_hit_log, admission_log):
                        if os.path.exists(path):
                            os.remove(path)
                    torch.ops.vulkan_prepack.reset_fallback_counters()
                    self_cpu, self_vulkan = make_float_buffer_operand(
                        [2, 3],
                        7300,
                    )
                    other_cpu, other_vulkan = make_direct_operand(
                        [3],
                        torch.float32,
                        7301,
                    )
                    if os.path.exists(admission_log):
                        os.remove(admission_log)
                    expected = self_cpu / other_cpu
                    actual = (self_vulkan / other_vulkan).cpu()
                    torch.testing.assert_close(actual, expected, atol=1e-4, rtol=1e-4)
                    assert_admission_event(case, {
                        "outcome": "reject",
                        "phase": "generated_options",
                        "predicate": (
                            "elementwise_float_tensor_tensor_buffer_broadcast_"
                            "attributes_match"
                        ),
                        "reason_code": "attribute_mismatch",
                        "source": "generated",
                    })

                for _, case, expect_native_route in (
                    contract_spec_utils.iter_shape_envelope_contract_cases(spec)
                ):
                    run_case(case, expect_native_route)
                run_attribute_reject_case()
            """
            self._run_repo_python_subprocess(
                script,
                extra_env={
                    "PYTORCH_VULKAN_OP_HIT_LOG": op_hit_log_name,
                    "PYTORCH_VULKAN_CONTRACT_ADMISSION_LOG": admission_log_name,
                },
                error_prefix=(
                    "ElementwiseBroadcast generated contract spec failed."
                ),
            )
        finally:
            for path in log_paths:
                if os.path.exists(path):
                    os.remove(path)

    def test_float_buffer_view_inplace_binary_ops(self):
        torch.manual_seed(0)
        x = torch.randn(1, 17, 384, dtype=torch.float32)
        gamma = torch.randn(384, dtype=torch.float32)

        with torch.inference_mode():
            expected_tensor = x.clone()
            expected_tensor[:, 1:, :] *= gamma
            expected_scalar = x.clone()
            expected_scalar[:, 1:, :] *= 0.5

            previous = torch.ops.vulkan_prepack.swap_runtime_label(
                "depth.dino.backbone.block"
            )
            try:
                tensor_case = x.to("vulkan")
                tensor_case[:, 1:, :] *= gamma.to("vulkan")
                actual_tensor = tensor_case.cpu()

                scalar_case = x.to("vulkan")
                scalar_case[:, 1:, :] *= 0.5
                actual_scalar = scalar_case.cpu()
            finally:
                torch.ops.vulkan_prepack.swap_runtime_label(previous)

        self._assert_outputs_close(expected_tensor, actual_tensor, atol=1e-4, rtol=1e-4)
        self._assert_outputs_close(expected_scalar, actual_scalar, atol=1e-4, rtol=1e-4)

    def test_float_buffer_gelu_ops(self):
        torch.manual_seed(0)
        x = torch.randn(17, 384, dtype=torch.float32)
        weight = torch.randn(384, 384, dtype=torch.float32)
        bias = torch.randn(384, dtype=torch.float32)

        with torch.inference_mode():
            expected = F.gelu(F.linear(x, weight, bias), approximate="tanh")

            previous = torch.ops.vulkan_prepack.swap_runtime_label(
                "depth.dino.backbone.block"
            )
            x_vulkan = x.to("vulkan")
            weight_vulkan = weight.to("vulkan")
            bias_vulkan = bias.to("vulkan")
            try:
                actual = F.gelu(
                    F.linear(x_vulkan, weight_vulkan, bias_vulkan),
                    approximate="tanh",
                ).cpu()
            finally:
                torch.ops.vulkan_prepack.swap_runtime_label(previous)

        self._assert_outputs_close(expected, actual, atol=1e-4, rtol=1e-4)

    def test_float_buffer_gelu_large_negative_values_are_finite(self):
        x = torch.full((601, 1536), -13.149483680725098, dtype=torch.float32)
        x[281, 1385] = -13.149483680725098
        x[281, 1386] = -15.0
        x[281, 1387] = -20.0

        with torch.inference_mode():
            expected = F.gelu(x, approximate="tanh")
            previous = torch.ops.vulkan_prepack.swap_runtime_label(
                "depth.dino.backbone.block"
            )
            try:
                actual = F.gelu(x.to("vulkan"), approximate="tanh").cpu()
            finally:
                torch.ops.vulkan_prepack.swap_runtime_label(previous)

        self.assertTrue(torch.isfinite(actual).all().item())
        self._assert_outputs_close(expected, actual, atol=1e-5, rtol=1e-5)

    def test_float_buffer_binary_scalar_avoids_texture_staging(self):
        materialize_log_name = "float_buffer_binary_scalar_materialize_test.log"
        op_hit_log_name = "float_buffer_binary_scalar_op_hit_test.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        materialize_log_path = os.path.join(repo_root, materialize_log_name)
        op_hit_log_path = os.path.join(repo_root, op_hit_log_name)
        for path in (materialize_log_path, op_hit_log_path):
            if os.path.exists(path):
                os.remove(path)

        try:
            script = """
                import torch
                import torch.nn.functional as F

                assert hasattr(torch.ops.vulkan_prepack, "swap_runtime_label")

                torch.manual_seed(0)
                x = torch.randn(17, 384, dtype=torch.float32)
                weight = torch.randn(384, 384, dtype=torch.float32)
                bias = torch.randn(384, dtype=torch.float32)

                with torch.inference_mode():
                    expected_base = F.linear(x, weight, bias)

                    previous = torch.ops.vulkan_prepack.swap_runtime_label(
                        "depth.dino.backbone.block"
                    )
                    x_vulkan = x.to("vulkan")
                    weight_vulkan = weight.to("vulkan")
                    bias_vulkan = bias.to("vulkan")
                    try:
                        actual_base = F.linear(x_vulkan, weight_vulkan, bias_vulkan)
                        actual_add = torch.ops.aten.add.Scalar(
                            actual_base, 0.25, alpha=1
                        ).cpu()
                        actual_sub = torch.ops.aten.sub.Scalar(
                            actual_base, 0.75, alpha=1
                        ).cpu()
                        actual_mul = torch.ops.aten.mul.Scalar(
                            actual_base, -1.5
                        ).cpu()
                        actual_div = torch.ops.aten.div.Scalar(
                            actual_base, 2.0
                        ).cpu()
                    finally:
                        torch.ops.vulkan_prepack.swap_runtime_label(previous)

                torch.testing.assert_close(actual_add, expected_base + 0.25, atol=1e-4, rtol=1e-4)
                torch.testing.assert_close(actual_sub, expected_base - 0.75, atol=1e-4, rtol=1e-4)
                torch.testing.assert_close(actual_mul, expected_base * -1.5, atol=1e-4, rtol=1e-4)
                torch.testing.assert_close(actual_div, expected_base / 2.0, atol=1e-4, rtol=1e-4)
                print(float(actual_add.sum() + actual_sub.sum() + actual_mul.sum() + actual_div.sum()))
            """

            self._run_repo_python_subprocess(
                script,
                extra_env={
                    "PYTORCH_VULKAN_MATERIALIZE_LOG": materialize_log_name,
                    "PYTORCH_VULKAN_OP_HIT_LOG": op_hit_log_name,
                },
                error_prefix="float buffer scalar materialize subprocess failed.",
            )

            self.assertTrue(os.path.exists(op_hit_log_path))
            with open(op_hit_log_path, "r", encoding="utf-8") as log_file:
                op_hit_text = log_file.read()

            self.assertGreaterEqual(
                op_hit_text.count("op=aten::binary_op.scalar_buffer_float"),
                4,
            )

            if os.path.exists(materialize_log_path):
                with open(materialize_log_path, "r", encoding="utf-8") as log_file:
                    materialize_log_text = log_file.read()

                self.assertNotIn(
                    "caller=binary_op path=buffer_to_texture_via_staging",
                    materialize_log_text,
                )
        finally:
            for path in (materialize_log_path, op_hit_log_path):
                if os.path.exists(path):
                    os.remove(path)

