    def test_direct_buffer_image_readback_uses_raw_copy(self):
        log_name = "direct_buffer_image_readback_raw_copy_test.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        log_path = os.path.join(repo_root, log_name)
        if os.path.exists(log_path):
            os.remove(log_path)

        try:
            script = """
                import torch

                torch.manual_seed(0)
                shapes = [
                    (1, 3, 64, 96),
                    (1, 128, 128, 128),
                ]
                for shape in shapes:
                    x = torch.randn(shape, dtype=torch.float32)
                    x_vulkan = x.to("vulkan")
                    with torch.inference_mode():
                        for _ in range(3):
                            actual = x_vulkan.cpu()
                            torch.testing.assert_close(
                                actual,
                                x,
                                atol=1e-5,
                                rtol=1e-5,
                            )
                print("OK")
            """

            self._run_repo_python_subprocess(
                script,
                extra_env={"PYTORCH_VULKAN_OP_HIT_LOG": log_name},
                error_prefix="Direct-buffer image readback subprocess failed.",
            )

            self.assertTrue(os.path.exists(log_path))
            with open(log_path, "r", encoding="utf-8") as log_file:
                log_text = log_file.read()

            self.assertTrue(
                "op=aten::copy_.vulkan_to_cpu_buffer_direct_raw" in log_text
                or "op=aten::copy_.vulkan_to_cpu_buffer_direct_metadata_unpack"
                in log_text
            )
            self.assertNotIn(
                "op=aten::copy_.vulkan_to_cpu_buffer_packed_shader",
                log_text,
            )
        finally:
            if os.path.exists(log_path):
                os.remove(log_path)

    def test_high_rank_buffer_metadata_view_readback_uses_snapshot_unpack(self):
        log_name = "high_rank_metadata_view_readback_test.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        log_path = os.path.join(repo_root, log_name)
        if os.path.exists(log_path):
            os.remove(log_path)

        try:
            script = """
                import torch

                torch.manual_seed(0)
                x = torch.arange(64, dtype=torch.float32).reshape(1, 2, 2, 2, 2, 4)
                with torch.inference_mode():
                    x_vulkan = x.to("vulkan")
                    view = x_vulkan.permute(0, 5, 1, 2, 3, 4)
                    actual = view.cpu()
                    expected = x.permute(0, 5, 1, 2, 3, 4)
                    torch.testing.assert_close(actual, expected)
                print("OK")
            """

            self._run_repo_python_subprocess(
                script,
                extra_env={"PYTORCH_VULKAN_OP_HIT_LOG": log_name},
                error_prefix=(
                    "High-rank metadata-view readback subprocess failed."
                ),
            )

            self.assertTrue(os.path.exists(log_path))
            with open(log_path, "r", encoding="utf-8") as log_file:
                log_text = log_file.read()

            self.assertIn(
                "op=aten::copy_.vulkan_to_cpu_buffer_snapshot_metadata_readback",
                log_text,
            )
            self.assertIn(
                "op=aten::copy_.vulkan_to_cpu_buffer_metadata_unpack",
                log_text,
            )
            self.assertNotIn(
                "op=aten::copy_.vulkan_to_cpu_buffer_direct_raw",
                log_text,
            )
        finally:
            if os.path.exists(log_path):
                os.remove(log_path)

    def test_diffusion_style_conv2d_matches_cpu_reference(self):
        log_name = "diffusion_style_conv2d_vulkan_route_test.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        log_path = os.path.join(repo_root, log_name)
        if os.path.exists(log_path):
            os.remove(log_path)

        try:
            previous_route_log = os.environ.get("PYTORCH_VULKAN_ROUTE_LOG")
            os.environ["PYTORCH_VULKAN_ROUTE_LOG"] = log_path
            torch.manual_seed(0)
            cases = [
                (1, 64, 64, 16, 24),
                (1, 96, 32, 16, 24),
                (1, 128, 128, 16, 24),
                (1, 64, 64, 63, 96),
                (1, 128, 3, 64, 96),
            ]

            with torch.inference_mode():
                for batch, in_channels, out_channels, height, width in cases:
                    x = torch.randn(batch, in_channels, height, width)
                    module_cpu = torch.nn.Conv2d(
                        in_channels,
                        out_channels,
                        kernel_size=3,
                        stride=1,
                        padding=1,
                        bias=True).eval()
                    module_vulkan = torch.nn.Conv2d(
                        in_channels,
                        out_channels,
                        kernel_size=3,
                        stride=1,
                        padding=1,
                        bias=True).eval()
                    module_vulkan.load_state_dict(module_cpu.state_dict())
                    module_vulkan = module_vulkan.to("vulkan")

                    expected = self._conv2d_unfold_reference(module_cpu, x)
                    actual = module_vulkan(x.to("vulkan")).cpu()
                    self._assert_outputs_close_with_accuracy(
                        expected,
                        actual,
                        atol=5e-3,
                        rtol=5e-3,
                        label=(
                            "diffusion_style_conv2d "
                            f"shape={(batch, in_channels, height, width)}"))

            if os.path.exists(log_path):
                with open(log_path, "r", encoding="utf-8") as log_file:
                    log_text = log_file.read()
                self.assertNotIn("decision=HardFail", log_text)
        finally:
            if previous_route_log is None:
                os.environ.pop("PYTORCH_VULKAN_ROUTE_LOG", None)
            else:
                os.environ["PYTORCH_VULKAN_ROUTE_LOG"] = previous_route_log
            if os.path.exists(log_path):
                os.remove(log_path)

