    def test_upsample_bicubic2d_out(self):
        torch.manual_seed(0)
        x_cpu = torch.randn(1, 3, 8, 8)
        x_vulkan = x_cpu.to("vulkan")

        with torch.inference_mode():
            expected = F.interpolate(
                x_cpu,
                size=(11, 13),
                mode="bicubic",
                align_corners=False)
            out_vulkan = torch.empty((1, 3, 5, 5), device="vulkan")
            actual = torch.ops.aten.upsample_bicubic2d.out(
                x_vulkan,
                [11, 13],
                False,
                None,
                None,
                out=out_vulkan).cpu()

        self._assert_outputs_close(expected, actual, atol=5e-3, rtol=5e-3)
        self._assert_outputs_close(expected, out_vulkan.cpu(), atol=1e-3, rtol=1e-3)

    def test_conv2d_module_with_vulkan_weights(self):
        torch.manual_seed(0)

        module_cpu = torch.nn.Conv2d(
            3,
            12,
            kernel_size=4,
            stride=4,
            bias=True).eval()
        module_vulkan = torch.nn.Conv2d(
            3,
            12,
            kernel_size=4,
            stride=4,
            bias=True).eval()
        module_vulkan.load_state_dict(module_cpu.state_dict())
        module_vulkan = module_vulkan.to("vulkan")

        module_cpu_nobias = torch.nn.Conv2d(
            3,
            12,
            kernel_size=4,
            stride=4,
            bias=False).eval()
        module_vulkan_nobias = torch.nn.Conv2d(
            3,
            12,
            kernel_size=4,
            stride=4,
            bias=False).eval()
        module_vulkan_nobias.load_state_dict(module_cpu_nobias.state_dict())
        module_vulkan_nobias = module_vulkan_nobias.to("vulkan")

        x_cpu = torch.randn(1, 3, 16, 20)
        x_vulkan = x_cpu.to("vulkan")

        with torch.inference_mode():
            expected = module_cpu(x_cpu)
            actual = module_vulkan(x_vulkan).cpu()
            self._assert_outputs_close(
                expected,
                actual,
                atol=1e-4,
                rtol=1e-4)

            actual_functional = F.conv2d(
                x_vulkan,
                module_vulkan.weight,
                module_vulkan.bias,
                stride=4).cpu()
            self._assert_outputs_close(
                expected,
                actual_functional,
                atol=1e-4,
                rtol=1e-4)

            expected_nobias = module_cpu_nobias(x_cpu)
            actual_nobias = module_vulkan_nobias(x_vulkan).cpu()
            self._assert_outputs_close(
                expected_nobias,
                actual_nobias,
                atol=1e-4,
                rtol=1e-4)

    def test_large_pointwise_conv2d_module_with_vulkan_weights(self):
        import numpy as np

        torch.manual_seed(0)

        dav2_project_shapes = (
            (1, 384, 15, 10),
            (1, 384, 20, 13),
            (1, 384, 30, 20),
            (1, 384, 45, 30),
        )
        for shape in dav2_project_shapes:
            for out_channels in (192, 384):
                with self.subTest(shape=shape, out_channels=out_channels):
                    x_cpu = torch.randn(*shape)
                    x_vulkan = x_cpu.to("vulkan")
                    module_cpu = torch.nn.Conv2d(
                        384,
                        out_channels,
                        kernel_size=1,
                        bias=True).eval()
                    module_vulkan = torch.nn.Conv2d(
                        384,
                        out_channels,
                        kernel_size=1,
                        bias=True).eval()
                    module_vulkan.load_state_dict(module_cpu.state_dict())
                    module_vulkan = module_vulkan.to("vulkan")

                    with torch.inference_mode():
                        weight_np = module_cpu.weight.detach().numpy().reshape(
                            out_channels, shape[1])
                        bias_np = module_cpu.bias.detach().numpy()
                        expected = torch.from_numpy(
                            np.einsum(
                                "nchw,oc->nohw",
                                x_cpu.numpy(),
                                weight_np,
                                optimize=True)
                            + bias_np.reshape(1, out_channels, 1, 1))
                        actual = None
                        for _ in range(3):
                            current = module_vulkan(x_vulkan).cpu()
                            if actual is not None:
                                self._assert_outputs_close(
                                    actual,
                                    current,
                                    atol=1e-5,
                                    rtol=1e-5)
                            actual = current

                    self._assert_outputs_close(
                        expected,
                        actual,
                        atol=1e-4,
                        rtol=1e-4)

    def test_large_pointwise_conv2d_factorized_depth_vision_matches_cpu(self):
        torch.manual_seed(2730)
        channel_pairs = (
            (384, 192),
            (384, 256),
            (384, 384),
            (384, 512),
            (384, 768),
            (384, 1024),
            (768, 192),
            (768, 256),
            (768, 384),
            (768, 512),
            (768, 768),
            (768, 1024),
            (1024, 192),
            (1024, 256),
            (1024, 384),
            (1024, 512),
            (1024, 768),
            (1024, 1024),
        )
        spatial_pairs = (
            (10, 15),
            (13, 20),
            (20, 31),
            (30, 46),
            (40, 61),
            (50, 77),
        )
        as_linear_hit = "aten::convolution.buffer_float_1x1_as_linear"
        log_name = "large_pointwise_factorized_depth_vision_op_hit_test.log"
        log_path = os.path.join(REPO_ROOT, log_name)
        previous_op_hit_log = os.environ.get("PYTORCH_VULKAN_OP_HIT_LOG")
        os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = log_path
        try:
            for input_channels, out_channels in channel_pairs:
                for height, width in spatial_pairs:
                    with self.subTest(
                            input_channels=input_channels,
                            out_channels=out_channels,
                            height=height,
                            width=width):
                        if os.path.exists(log_path):
                            os.remove(log_path)
                        x_cpu = torch.randn(
                            1,
                            input_channels,
                            height,
                            width) * 0.1
                        x_vulkan = x_cpu.to("vulkan")
                        module_cpu = torch.nn.Conv2d(
                            input_channels,
                            out_channels,
                            kernel_size=1,
                            bias=True).eval()
                        module_vulkan = torch.nn.Conv2d(
                            input_channels,
                            out_channels,
                            kernel_size=1,
                            bias=True).eval()
                        module_vulkan.load_state_dict(module_cpu.state_dict())
                        module_vulkan = module_vulkan.to("vulkan")

                        with torch.inference_mode():
                            expected = module_cpu(x_cpu)
                            torch.ops.vulkan_prepack.reset_fallback_counters()
                            actual = module_vulkan(x_vulkan).cpu()

                        self._assert_outputs_close(
                            expected,
                            actual,
                            atol=1e-4,
                            rtol=1e-4)
                        self.assertEqual(
                            torch.ops.vulkan_prepack.cpu_fallback_count(),
                            0)
                        with open(log_path, "r", encoding="utf-8") as log_file:
                            op_hits = log_file.read()
                        self.assertIn(
                            "aten::convolution.buffer_float_1x1_skip."
                            "small_spatial_pointwise.depth_vision_projection",
                            op_hits)
                        self.assertIn(as_linear_hit, op_hits)
        finally:
            if previous_op_hit_log is None:
                os.environ.pop("PYTORCH_VULKAN_OP_HIT_LOG", None)
            else:
                os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = previous_op_hit_log
            if os.path.exists(log_path):
                os.remove(log_path)

    def test_large_pointwise_conv2d_token_slice_layout_preserves_generic(self):
        torch.manual_seed(2732)
        cases = (
            (384, 192, 20, 31),
            (1024, 256, 50, 77),
        )
        as_linear_hit = "aten::convolution.buffer_float_1x1_as_linear"
        contract_hit = (
            "aten::convolution.buffer_float_1x1_skip."
            "small_spatial_pointwise.depth_vision_projection"
        )
        log_name = "large_pointwise_token_slice_layout_op_hit_test.log"
        log_path = os.path.join(REPO_ROOT, log_name)
        previous_op_hit_log = os.environ.get("PYTORCH_VULKAN_OP_HIT_LOG")
        os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = log_path
        try:
            for input_channels, out_channels, height, width in cases:
                with self.subTest(
                        input_channels=input_channels,
                        out_channels=out_channels,
                        height=height,
                        width=width):
                    if os.path.exists(log_path):
                        os.remove(log_path)
                    token_count = height * width
                    tokens_cpu = (
                        torch.randn(1, token_count + 1, input_channels) * 0.05
                    )
                    x_cpu = tokens_cpu[:, 1:, :].transpose(1, 2).reshape(
                        1,
                        input_channels,
                        height,
                        width)
                    tokens_vulkan = tokens_cpu.to("vulkan")
                    x_vulkan = tokens_vulkan[:, 1:, :].transpose(1, 2).reshape(
                        1,
                        input_channels,
                        height,
                        width)
                    module_cpu = torch.nn.Conv2d(
                        input_channels,
                        out_channels,
                        kernel_size=1,
                        bias=True).eval()
                    module_vulkan = torch.nn.Conv2d(
                        input_channels,
                        out_channels,
                        kernel_size=1,
                        bias=True).eval()
                    module_vulkan.load_state_dict(module_cpu.state_dict())
                    module_vulkan = module_vulkan.to("vulkan")

                    with torch.inference_mode():
                        expected = module_cpu(x_cpu)
                        torch.ops.vulkan_prepack.reset_fallback_counters()
                        actual = module_vulkan(x_vulkan).cpu()

                    self._assert_outputs_close(
                        expected,
                        actual,
                        atol=1e-4,
                        rtol=1e-4)
                    self.assertEqual(
                        torch.ops.vulkan_prepack.cpu_fallback_count(),
                        0)
                    with open(log_path, "r", encoding="utf-8") as log_file:
                        op_hits = log_file.read()
                    self.assertIn(contract_hit, op_hits)
                    self.assertNotIn(as_linear_hit, op_hits)
                    self.assertIn(
                        "pointwise_route selected=generic "
                        "selected_plan=FloatBufferPointwise1x1",
                        op_hits)
                    self.assertIn("old_generic_retained=1", op_hits)
                    self.assertIn(
                        f"input=[1,{input_channels},{height},{width}]",
                        op_hits)
                    self.assertIn(f"input_offset={input_channels}", op_hits)
                    self.assertIn("input_direct=0", op_hits)
        finally:
            if previous_op_hit_log is None:
                os.environ.pop("PYTORCH_VULKAN_OP_HIT_LOG", None)
            else:
                os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = previous_op_hit_log
            if os.path.exists(log_path):
                os.remove(log_path)

    def test_large_pointwise_conv2d_unaligned_width_hard_fails(self):
        log_name = "large_pointwise_conv2d_unaligned_width_hard_fail.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        log_path = os.path.join(repo_root, log_name)
        if os.path.exists(log_path):
            os.remove(log_path)

        script = """
            import torch

            torch.manual_seed(0)
            x_cpu = torch.randn(1, 384, 7, 9)
            x_vulkan = x_cpu.to("vulkan")
            module_vulkan = torch.nn.Conv2d(
                384,
                192,
                kernel_size=1,
                bias=True).eval().to("vulkan")

            with torch.inference_mode():
                try:
                    module_vulkan(x_vulkan)
                except RuntimeError as exc:
                    message = str(exc)
                    print(message)
                    if (
                        "Vulkan failure failure_class=RouteHardFail"
                        not in message
                        or "KnownBadLargePointwiseConv" not in message
                    ):
                        raise
                else:
                    raise AssertionError(
                        "unaligned large pointwise conv should hard-fail")

            print("OK")
        """
        try:
            _, result = self._run_repo_python_subprocess(
                script,
                extra_env={"PYTORCH_VULKAN_FAILURE_LOG": log_name},
                error_prefix="large pointwise unaligned Vulkan conv subprocess failed.",
            )
            self.assertIn("OK", result.stdout)
            self.assertIn("KnownBadLargePointwiseConv", result.stdout)

            self.assertTrue(os.path.exists(log_path))
            with open(log_path, "r", encoding="utf-8") as log_file:
                log_text = log_file.read()
            self.assertIn("failure_class=RouteHardFail", log_text)
            self.assertIn("reason=KnownBadLargePointwiseConv", log_text)
        finally:
            if os.path.exists(log_path):
                os.remove(log_path)

