    def test_softmax_diffusion_score_shape_matches_cpu(self):
        torch.manual_seed(0)
        score_shapes = (
            (1, 640, 640),
            (5, 640, 640),
            (1, 504, 504),
            (5, 504, 504),
        )

        for shape in score_shapes:
            scores = torch.randn(*shape)

            expected = scores.softmax(-1)
            with torch.inference_mode():
                torch.ops.vulkan_prepack.reset_fallback_counters()
                actual = scores.to("vulkan").softmax(-1).cpu()

            self.assertEqual(actual, expected, rtol=1e-4, atol=1e-4)
            self.assertEqual(
                actual.sum(dim=-1),
                torch.ones(shape[0], shape[1]),
                rtol=1e-4,
                atol=1e-4,
            )
            self.assertEqual(torch.ops.vulkan_prepack.cpu_fallback_count(), 0)

    def test_softmax_diffusion_score_shape_guard(self):
        log_name = "softmax_diffusion_score_shape_guard_op_hit_test.log"
        log_path = os.path.join(REPO_ROOT, log_name)
        if os.path.exists(log_path):
            os.remove(log_path)

        previous_op_hit_log = os.environ.get("PYTORCH_VULKAN_OP_HIT_LOG")
        cases = (
            (2, 64, 64),
            (1, 65, 65),
            (1, 64, 65),
        )

        try:
            os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = log_path
            for shape in cases:
                with self.subTest(shape=shape):
                    scores = torch.randn(*shape)
                    expected = scores.softmax(-1)
                    with torch.inference_mode():
                        torch.ops.vulkan_prepack.reset_fallback_counters()
                        actual = scores.to("vulkan").softmax(-1).cpu()

                    self.assertEqual(actual, expected, rtol=1e-4, atol=1e-4)
                    self.assertEqual(torch.ops.vulkan_prepack.cpu_fallback_count(), 0)

            self.assertTrue(os.path.exists(log_path))
            with open(log_path, "r", encoding="utf-8") as log_file:
                op_hits = [
                    line.split("op=", 1)[1].split()[0]
                    for line in log_file
                    if "op=" in line
                ]
            self.assertIn(
                "aten::_softmax.buffer_lastdim_known_bad_texture_fallback",
                op_hits,
            )
            self.assertNotIn("aten::_softmax.buffer_lastdim", op_hits)
        finally:
            if previous_op_hit_log is None:
                os.environ.pop("PYTORCH_VULKAN_OP_HIT_LOG", None)
            else:
                os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = previous_op_hit_log
            if os.path.exists(log_path):
                os.remove(log_path)

    def test_sdpa_score_softmax_contract_generated_spec(self):
        spec = _load_vulkan_contract_spec("sdpa_score_softmax_contract.json")
        op_hit_log_name = contract_spec_utils.contract_log_name(
            spec,
            {"name": "generated"},
            "op_hit_test.log",
        )
        op_hit_log_path = os.path.join(REPO_ROOT, op_hit_log_name)
        if os.path.exists(op_hit_log_path):
            os.remove(op_hit_log_path)

        previous_op_hit_log = os.environ.get("PYTORCH_VULKAN_OP_HIT_LOG")

        def read_op_hits():
            if not os.path.exists(op_hit_log_path):
                return []
            with open(op_hit_log_path, "r", encoding="utf-8") as log_file:
                return [
                    line.split("op=", 1)[1].split()[0]
                    for line in log_file
                    if "op=" in line
                ]

        def dtype_for_case(case):
            return {
                "float32": torch.float32,
            }[case["dtype"]]

        try:
            os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = op_hit_log_path
            for _, case, expect_native_route in (
                contract_spec_utils.iter_contract_cases(spec)
            ):
                with self.subTest(case=case["name"]):
                    if os.path.exists(op_hit_log_path):
                        os.remove(op_hit_log_path)
                    torch.manual_seed(6000 + len(case["name"]))
                    scores = torch.randn(
                        *case["shape"],
                        dtype=dtype_for_case(case),
                    )

                    expected = scores.softmax(case["dim"])
                    with torch.inference_mode():
                        torch.ops.vulkan_prepack.reset_fallback_counters()
                        actual = scores.to("vulkan").softmax(case["dim"]).cpu()

                    self.assertEqual(actual, expected, rtol=1e-4, atol=1e-4)
                    fallback_count = torch.ops.vulkan_prepack.cpu_fallback_count()
                    op_hits = read_op_hits()
                    if expect_native_route:
                        self.assertFalse(case["expected_cpu_fallback"])
                        self.assertEqual(fallback_count, 0)
                        self.assertIn(case["expected_route_label"], op_hits)
                    else:
                        self.assertNotIn(spec["route_label"], op_hits)
                        if "expected_guard_route_label" in case:
                            self.assertIn(case["expected_guard_route_label"], op_hits)
                        if not case.get("expected_cpu_fallback", True):
                            self.assertEqual(fallback_count, 0)
        finally:
            if previous_op_hit_log is None:
                os.environ.pop("PYTORCH_VULKAN_OP_HIT_LOG", None)
            else:
                os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = previous_op_hit_log
            if os.path.exists(op_hit_log_path):
                os.remove(op_hit_log_path)

    def test_vulkan_dispatch_tables_expose_backend_kernels(self):
        dispatch_expectations = {
            "aten::mm": ("Vulkan: registered at", "Mm.cpp"),
            "aten::bmm": ("Vulkan: registered at", "Mm.cpp"),
            "aten::_softmax": ("Vulkan: registered at", "Softmax.cpp"),
            "aten::group_norm": ("Vulkan: registered at", "Mean.cpp"),
            "aten::_scaled_dot_product_attention_math": (
                "Vulkan: registered at",
                "Softmax.cpp",
            ),
            "vulkan_prepack::run_linear_context": (
                "Vulkan: registered at",
                "Register.cpp",
            ),
        }

        for opname, expected_substrings in dispatch_expectations.items():
            with self.subTest(opname=opname):
                table = torch._C._dispatch_dump_table(opname)
                for expected_substring in expected_substrings:
                    self.assertIn(expected_substring, table)

        linear_table = torch._C._dispatch_dump_table("aten::linear")
        self.assertIn("CompositeImplicitAutograd", linear_table)
        self.assertIn("RegisterCompositeImplicitAutograd", linear_table)
        self.assertNotIn("Mm.cpp", linear_table)

        public_sdpa_table = torch._C._dispatch_dump_table(
            "aten::scaled_dot_product_attention"
        )
        self.assertIn("CompositeImplicitAutograd", public_sdpa_table)
        self.assertFalse(
            hasattr(torch.ops.vulkan_prepack, "scaled_dot_product_attention")
        )

        layer_norm_table = torch._C._dispatch_dump_table("aten::layer_norm")
        self.assertIn("CompositeImplicitAutograd", layer_norm_table)
        self.assertNotIn("Layernorm.cpp", layer_norm_table)

        native_layer_norm_table = torch._C._dispatch_dump_table(
            "aten::native_layer_norm"
        )
        self.assertIn("CompositeExplicitAutograd", native_layer_norm_table)
        self.assertNotIn("NativeLayerNorm.cpp", native_layer_norm_table)

        rms_norm_table = torch._C._dispatch_dump_table("aten::rms_norm")
        self.assertIn("CompositeImplicitAutograd", rms_norm_table)
        self.assertNotIn("RMSNorm.cpp", rms_norm_table)

    def test_vulkan_runtime_op_hit_logging(self):
        log_name = "vulkan_op_hit_logging_test.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        log_path = os.path.join(repo_root, log_name)
        if os.path.exists(log_path):
            os.remove(log_path)

        try:
            script = """
                import torch
                import torch.nn.functional as F

                torch.manual_seed(0)
                with torch.inference_mode():
                    x = torch.randn(1, 16, 32, dtype=torch.float32).to("vulkan")
                    w = torch.randn(64, 32, dtype=torch.float32).to("vulkan")
                    b = torch.randn(64, dtype=torch.float32).to("vulkan")
                    F.linear(x, w, b)

                    ctx = torch.ops.vulkan_prepack.create_linear_context(
                        w.clone().t(),
                        b,
                    )
                    torch.ops.vulkan_prepack.run_linear_context(x, ctx)

                    mm_a = torch.randn(8, 8, dtype=torch.float32).to("vulkan")
                    mm_b = torch.randn(8, 8, dtype=torch.float32).to("vulkan")
                    torch.mm(mm_a, mm_b)

                    bmm_a = torch.randn(2, 8, 8, dtype=torch.float32).to("vulkan")
                    bmm_b = torch.randn(2, 8, 8, dtype=torch.float32).to("vulkan")
                    torch.bmm(bmm_a, bmm_b)

                    s = torch.randn(2, 3, 4, dtype=torch.float32).to("vulkan")
                    F.softmax(s, dim=-1)

                    ln_x = torch.randn(1, 17, 32, dtype=torch.float32).to("vulkan")
                    ln_weight = torch.randn(32, dtype=torch.float32)
                    ln_bias = torch.randn(32, dtype=torch.float32)
                    F.layer_norm(
                        ln_x,
                        (32,),
                        ln_weight,
                        ln_bias,
                        1e-5,
                    )
                    F.rms_norm(
                        ln_x,
                        (32,),
                        ln_weight,
                        1e-5,
                    )
                    gn_x = torch.randn(2, 8, 7, 7, dtype=torch.float32).to("vulkan")
                    gn_weight = torch.randn(8, dtype=torch.float32)
                    gn_bias = torch.randn(8, dtype=torch.float32)
                    torch.nn.functional.group_norm(
                        gn_x,
                        4,
                        gn_weight,
                        gn_bias,
                        1e-5,
                    )

                    q = torch.randn(2, 9, 8, dtype=torch.float32).to("vulkan")
                    k = torch.randn(2, 7, 8, dtype=torch.float32).to("vulkan")
                    v = torch.randn(2, 7, 8, dtype=torch.float32).to("vulkan")
                    torch.ops.aten._scaled_dot_product_attention_math(
                        q,
                        k,
                        v,
                        None,
                        0.0,
                        False,
                        None,
                        enable_gqa=False,
                    )[0]
                print("ok")
            """

            _, result = self._run_repo_python_subprocess(
                script,
                extra_env={"PYTORCH_VULKAN_OP_HIT_LOG": log_name},
                error_prefix="Vulkan op-hit logging subprocess failed.",
            )
            self.assertIn("ok", result.stdout)

            self.assertTrue(os.path.exists(log_path))
            with open(log_path, "r", encoding="utf-8") as log_file:
                log_text = log_file.read()

            for op_name in (
                "aten::linear.buffer_float_bias",
                "vulkan_prepack::run_linear_context",
                "aten::mm",
                "aten::bmm",
                "aten::_softmax",
                "aten::layer_norm",
                "aten::native_layer_norm.buffer_width",
                "aten::rms_norm",
                "aten::rms_norm.fused_width",
                "aten::_scaled_dot_product_attention_math",
            ):
                with self.subTest(op_name=op_name):
                    self.assertIn(f"op={op_name}", log_text)
        finally:
            if os.path.exists(log_path):
                os.remove(log_path)

