    def test_vulkan_addmm_addend_does_not_poison_weight_cache_key(self):
        torch.manual_seed(0)
        torch.ops.vulkan_prepack.reset_linear_pack_residency_snapshot()
        torch.ops.vulkan_prepack.reset_packed_weight_residency_snapshot()
        weight_cpu = torch.randn(128, 64)
        x_cpu = torch.randn(2, 64)
        weight = weight_cpu.to("vulkan")
        x = x_cpu.to("vulkan")

        with torch.inference_mode():
            for _ in range(5):
                bias = torch.randn(2, 128).to("vulkan")
                y = torch.addmm(bias, x, weight.t(), beta=0.25, alpha=1.0)
        torch.ops.vulkan_prepack.synchronize()

        self.assertEqual(y.cpu(), torch.addmm(bias.cpu(), x_cpu, weight_cpu.t(), beta=0.25))
        rows = torch.ops.vulkan_prepack.linear_pack_residency_snapshot()
        self.assertTrue(
            any(
                "weight_shape=[64,128]" in row
                and "count=5" in row
                and "created=1" in row
                and "reused=4" in row
                for row in rows
            )
        )
        packed_rows = torch.ops.vulkan_prepack.packed_weight_residency_snapshot()
        self.assertTrue(
            any(
                "packed_weight_residency_summary" in row
                and "hits=4" in row
                for row in packed_rows
            )
        )
        self.assertTrue(
            any(
                "kind=Linear" in row
                and "logical_weight_shape=[64,128]" in row
                and "bias_source_key=0" in row
                for row in packed_rows
            )
        )

    def test_vulkan_vision_stack_execution_manifest_reports_capture_blocker(self):
        torch.manual_seed(0)
        embed_dim = 384
        num_heads = 6
        hidden_dim = 768
        token_count = 601
        norm_eps = 1.0e-6

        def randn(*sizes):
            return torch.randn(*sizes, dtype=torch.float32) * 0.02

        context = torch.ops.vulkan_prepack.create_vision_backbone_block_context(
            randn(embed_dim),
            randn(embed_dim),
            norm_eps,
            randn(embed_dim * 3, embed_dim),
            randn(embed_dim * 3),
            num_heads,
            randn(embed_dim, embed_dim),
            randn(embed_dim),
            randn(embed_dim),
            randn(embed_dim),
            randn(embed_dim),
            norm_eps,
            randn(hidden_dim, embed_dim),
            randn(hidden_dim),
            randn(embed_dim, hidden_dim),
            randn(embed_dim),
            randn(embed_dim),
            "depth.dino.backbone.stack.manifest.block0",
        )
        stack_context = torch.ops.vulkan_prepack.create_vision_backbone_stack_context(
            [context],
            num_heads,
            embed_dim // num_heads,
            embed_dim,
            hidden_dim,
        )
        x = randn(1, token_count, embed_dim).to("vulkan")

        torch.ops.vulkan_prepack.reset_stack_execution_manifest()
        torch.ops.vulkan_prepack.reset_fallback_phase_counters()

        with torch.inference_mode():
            outputs = torch.ops.vulkan_prepack.run_vision_backbone_stack_context(
                x,
                stack_context,
                [0],
            )
            torch.ops.vulkan_prepack.synchronize()

        self.assertEqual(len(outputs), 1)
        rows = torch.ops.vulkan_prepack.stack_execution_manifest()
        self.assertGreater(len(rows), 0)
        for phase in (
            "phase=norm1",
            "phase=qkv_linear",
            "phase=qkv_transform",
            "phase=attention",
            "phase=proj_linear",
            "phase=residual1",
            "phase=norm2",
            "phase=fc1_gelu",
            "phase=fc2",
            "phase=residual2",
            "phase=intermediate_capture",
        ):
            self.assertTrue(any(phase in row for row in rows), phase)
        self.assertTrue(
            any(
                "op=vulkan_prepack::vision_stack_attention_direct" in row
                and "safe_to_capture=0" in row
                for row in rows
            )
        )
        self.assertTrue(
            any(
                "phase=intermediate_capture" in row
                and "escapes_stack=1" in row
                and "requested_intermediate=1" in row
                for row in rows
            )
        )
        readiness = torch.ops.vulkan_prepack.stack_capture_readiness()
        self.assertEqual(readiness[0], 0)
        self.assertEqual(readiness[1], 1)
        self.assertEqual(readiness[2], 1)
        self.assertEqual(readiness[3], 1)
        self.assertEqual(readiness[4], 1)
        self.assertEqual(readiness[5], 1)
        self.assertEqual(readiness[6], 1)
        self.assertEqual(readiness[7], 1)
        self.assertEqual(readiness[8], 0)
        phase_counters = torch.ops.vulkan_prepack.fallback_phase_counters()
        self.assertEqual(phase_counters[3], 0)

    def test_vulkan_vision_backbone_block_context_with_attention_bias_matches_reference(self):
        torch.manual_seed(0)
        embed_dim = 32
        num_heads = 4
        hidden_dim = 64
        token_count = 17

        x = torch.randn(1, token_count, embed_dim, dtype=torch.float32)
        norm1_weight = torch.randn(embed_dim, dtype=torch.float32)
        norm1_bias = torch.randn(embed_dim, dtype=torch.float32)
        qkv_weight = torch.randn(embed_dim * 3, embed_dim, dtype=torch.float32)
        qkv_bias = torch.randn(embed_dim * 3, dtype=torch.float32)
        attention_bias = torch.randn(num_heads, token_count, token_count, dtype=torch.float32) * 0.01
        proj_weight = torch.randn(embed_dim, embed_dim, dtype=torch.float32)
        proj_bias = torch.randn(embed_dim, dtype=torch.float32)
        ls1_gamma = torch.randn(embed_dim, dtype=torch.float32)
        norm2_weight = torch.randn(embed_dim, dtype=torch.float32)
        norm2_bias = torch.randn(embed_dim, dtype=torch.float32)
        fc1_weight = torch.randn(hidden_dim, embed_dim, dtype=torch.float32)
        fc1_bias = torch.randn(hidden_dim, dtype=torch.float32)
        fc2_weight = torch.randn(embed_dim, hidden_dim, dtype=torch.float32)
        fc2_bias = torch.randn(embed_dim, dtype=torch.float32)
        ls2_gamma = torch.randn(embed_dim, dtype=torch.float32)

        norm_eps = 1.0e-6
        head_dim = embed_dim // num_heads

        def stable_attention(q, k, v, attention_bias=None):
            scores = torch.bmm(q, k.transpose(1, 2))
            if attention_bias is not None:
                scores = scores + attention_bias
            shifted = scores - scores.max(dim=-1, keepdim=True).values
            probs = torch.exp(shifted)
            probs = probs / probs.sum(dim=-1, keepdim=True)
            return torch.bmm(probs, v)

        def reference(inp):
            norm1 = F.layer_norm(inp, (embed_dim,), norm1_weight, norm1_bias, norm_eps)
            qkv = F.linear(norm1.reshape(token_count, embed_dim), qkv_weight, None)
            q, k, v = qkv.chunk(3, dim=1)
            q = (
                q + qkv_bias[:embed_dim]
            ).reshape(token_count, num_heads, head_dim).permute(1, 0, 2)
            k = (
                k + qkv_bias[embed_dim : 2 * embed_dim]
            ).reshape(token_count, num_heads, head_dim).permute(1, 0, 2)
            v = (
                v + qkv_bias[2 * embed_dim :]
            ).reshape(token_count, num_heads, head_dim).permute(1, 0, 2)
            q = q * (head_dim ** -0.5)
            attn = stable_attention(q, k, v, attention_bias)
            attn = attn.permute(1, 0, 2).reshape(token_count, embed_dim)
            attn = F.linear(attn, proj_weight, proj_bias).reshape(1, token_count, embed_dim)
            hidden = inp + attn * ls1_gamma
            norm2 = F.layer_norm(hidden, (embed_dim,), norm2_weight, norm2_bias, norm_eps)
            mlp = F.linear(norm2, fc1_weight, fc1_bias)
            mlp = F.gelu(mlp)
            mlp = F.linear(mlp, fc2_weight, fc2_bias)
            return hidden + mlp * ls2_gamma

        expected = reference(x)
        with torch.inference_mode():
            context = torch.ops.vulkan_prepack.create_vision_backbone_block_context_with_attention_bias(
                norm1_weight,
                norm1_bias,
                norm_eps,
                qkv_weight,
                qkv_bias,
                attention_bias,
                num_heads,
                proj_weight,
                proj_bias,
                ls1_gamma,
                norm2_weight,
                norm2_bias,
                norm_eps,
                fc1_weight,
                fc1_bias,
                fc2_weight,
                fc2_bias,
                ls2_gamma,
                "depth.beit.backbone.block.test",
            )
            actual = torch.ops.vulkan_prepack.run_vision_backbone_block_context(
                x.to("vulkan"),
                context,
            ).cpu()

        self._assert_outputs_close(expected, actual, atol=6e-3, rtol=6e-3)

    def test_vulkan_planning_runtime_ops_expose_scheduler_bridge(self):
        script = """
            import torch

            assert hasattr(torch.ops.vulkan_prepack, "query_runtime_policy")
            assert hasattr(torch.ops.vulkan_prepack, "create_kv_cache_storage_for_request")
            assert hasattr(torch.ops.vulkan_prepack, "create_scratch_arena_storage_for_request")
            assert hasattr(torch.ops.vulkan_prepack, "run_scheduled_gated_delta_rule_chunk")
            assert hasattr(torch.ops.vulkan_prepack, "run_scheduled_gated_delta_rule_recurrent")

            prototype = torch.randn(1, dtype=torch.float32).to("vulkan")
            decode_policy = list(torch.ops.vulkan_prepack.query_runtime_policy(
                prototype,
                11,  # LLMDecode
                2,   # LLM
                2,   # Decode
                0,   # Input
            ))
            cache_policy = list(torch.ops.vulkan_prepack.query_runtime_policy(
                prototype,
                3,   # AttentionCache
                2,   # LLM
                2,   # Decode
                3,   # Cache
            ))
            vision_policy = list(torch.ops.vulkan_prepack.query_runtime_policy(
                prototype,
                9,   # VisionBackbone
                1,   # Vision
                3,   # Backbone
                0,   # Input
            ))

            assert len(decode_policy) == 21
            assert len(vision_policy) == 21
            assert decode_policy[0] == 2  # backend_route=Split
            assert decode_policy[6] == 1  # has_scratch_plan
            assert cache_policy[1] == 1  # has_kv_cache_plan
            assert decode_policy[11] == 1  # linear_kernel_family=UnifiedBufferView
            assert decode_policy[13] == 3  # attention_kernel_family=SplitCoordinator
            assert cache_policy[13] == 3  # attention_kernel_family=SplitCoordinator
            assert decode_policy[14] == 1  # has_boundary_plan
            assert decode_policy[15] == 1  # boundary_kind=LLMLinearAttentionSplit
            assert decode_policy[18] == 1  # boundary_backend_owned_execution
            assert decode_policy[19] == 1  # boundary_requires_scratch
            assert decode_policy[20] == 1  # boundary_preferred_cpu_threads
            assert vision_policy[0] == 0  # backend_route=Vulkan
            assert vision_policy[6] == 1  # has_scratch_plan
            assert vision_policy[11] == 1  # linear_kernel_family=UnifiedBufferView
            assert vision_policy[14] == 0  # has_boundary_plan

            kv_cache = torch.ops.vulkan_prepack.create_kv_cache_storage_for_request(
                prototype,
                [1, 8, 16, 128],
                2,
                3,  # AttentionCache
                2,  # LLM
                2,  # Decode
                3,  # Cache
            )
            scratch = torch.ops.vulkan_prepack.create_scratch_arena_storage_for_request(
                prototype,
                65536,
                256,
                11,  # LLMDecode
                2,   # LLM
                2,   # Decode
                4,   # Scratch
            )

            assert kv_cache.device.type == "vulkan"
            assert scratch.device.type == "vulkan"
            assert kv_cache.numel() > 0
            assert scratch.numel() >= 65536
            print("ok")
        """

        _, result = self._run_repo_python_subprocess(
            script,
            error_prefix="Planning runtime bridge subprocess failed.",
        )
        self.assertIn("ok", result.stdout)

    def test_vulkan_capability_profile_minimum_masks_runtime_policy_features(self):
        policy_log_name = "vulkan_capability_profile_min_policy_test.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        policy_log_path = os.path.join(repo_root, policy_log_name)
        if os.path.exists(policy_log_path):
            os.remove(policy_log_path)

        try:
            script = """
                import torch

                prototype = torch.randn(1, dtype=torch.float32).to("vulkan")
                policy = list(torch.ops.vulkan_prepack.query_runtime_policy(
                    prototype,
                    9,  # VisionBackbone
                    1,  # Vision
                    3,  # Backbone
                    0,  # Input
                ))
                assert len(policy) == 21
                assert policy[0] == 0  # backend_route=Vulkan
                assert policy[11] != 3  # linear_kernel_family!=CooperativeMatrix
                assert policy[14] == 0  # has_boundary_plan
                print(policy)
            """
            self._run_repo_python_subprocess(
                script,
                extra_env={
                    "PYTORCH_VULKAN_CAPABILITY_PROFILE": "vk_min_1_1_compute",
                    "PYTORCH_VULKAN_RUNTIME_POLICY_LOG": policy_log_name,
                },
                error_prefix="Capability-profile runtime-policy subprocess failed.",
            )

            self.assertTrue(os.path.exists(policy_log_path))
            with open(policy_log_path, "r", encoding="utf-8") as log_file:
                policy_log_text = log_file.read()

            capability_line = next(
                line
                for line in policy_log_text.splitlines()
                if line.startswith("runtime_capabilities ")
            )
            capability_fields = dict(
                field.split("=", 1) for field in capability_line.split()[1:]
            )
            for field in (
                "has_shader_bfloat16",
                "has_shader_int8",
                "has_storage_buffer_8bit",
                "has_cooperative_matrix",
                "supports_int8_buffer_arithmetic",
            ):
                self.assertEqual(capability_fields[field], "0")

            policy_line = next(
                line
                for line in policy_log_text.splitlines()
                if line.startswith("runtime_policy ")
                and "workload=VisionBackbone" in line
                and "linear_kernel_family=" in line
            )
            policy_fields = dict(
                field.split("=", 1) for field in policy_line.split()[1:]
            )
            self.assertEqual(policy_fields["backend_route"], "Vulkan")
            self.assertEqual(
                policy_fields["linear_kernel_family"], "UnifiedBufferView"
            )
            self.assertEqual(policy_fields["has_boundary_plan"], "0")
            self.assertNotIn("linear_kernel_family=CooperativeMatrix", policy_log_text)
        finally:
            if os.path.exists(policy_log_path):
                os.remove(policy_log_path)

    def test_vulkan_vision_backbone_execution_program_bridge(self):
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        policy_log_name = "vulkan_vision_backbone_program_policy_test.log"
