                torch.manual_seed(0)
                x_cpu = torch.randn(1, 65, 384, dtype=torch.float32)
                w_cpu = torch.randn(1152, 384, dtype=torch.float32, requires_grad=True)
                b_cpu = torch.randn(1152, dtype=torch.float32, requires_grad=True)

                x = x_cpu.to("vulkan")
