                import torch.nn.functional as F

                assert hasattr(torch.ops.vulkan_prepack, "swap_runtime_label")

                torch.manual_seed(0)
                x = torch.randn(17, 384, dtype=torch.float32).to("vulkan")
                w = torch.randn(384, dtype=torch.float32).to("vulkan")
