    def test_linear_gelu_bridge_contract_generated_spec(self):
        spec = _load_vulkan_contract_spec("linear_gelu_bridge_contract.json")
        runtime_cases = [
            case
            for _, case, _ in contract_spec_utils.iter_shape_envelope_contract_cases(
                spec
            )
            if case.get("runtime_supported", True)
        ]
        case_log_names = [
            contract_spec_utils.contract_log_name(
                spec,
                case,
                "op_hit_test.log",
            )
            for case in runtime_cases
        ]
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        case_log_paths = [os.path.join(repo_root, name) for name in case_log_names]
        for path in case_log_paths:
            if os.path.exists(path):
                os.remove(path)

        try:
            script = """
                import json
                import os
                import re
                import sys
                import torch
                import torch.nn.functional as F
                sys.path.insert(
                    0,
                    os.path.join(os.getcwd(), "test", "vulkan_contract_specs"),
                )
                import contract_spec_utils

                spec_path = os.path.join(
                    os.getcwd(),
                    "test",
                    "vulkan_contract_specs",
                    "linear_gelu_bridge_contract.json",
                )
                with open(spec_path, encoding="utf-8") as handle:
                    spec = json.load(handle)

                def read_text(path):
                    if not os.path.exists(path):
                        return ""
                    with open(path, encoding="utf-8") as log_file:
                        return log_file.read()

                def to_vulkan_tensors(tensors):
                    x, weight, bias = tensors
                    return (
                        x.to("vulkan"),
                        weight.to("vulkan"),
                        bias.to("vulkan") if bias is not None else None,
                    )

                def run_linear_gelu(case, tensors):
                    x, weight, bias = tensors
                    return F.gelu(
                        F.linear(x, weight, bias),
                        approximate=case["gelu_approximate"],
                    )

                def run_with_mode(case, tensors):
                    context = (
                        torch.inference_mode()
                        if case["inference_mode_enabled"]
                        else torch.no_grad()
                    )
                    with context:
                        return run_linear_gelu(case, tensors)

                def make_tensors(case):
                    torch.manual_seed(7000 + len(case["name"]))
                    x = torch.randn(*case["input_shape"], dtype=torch.float32) * 0.1
                    weight = (
                        torch.randn(*case["weight_shape"], dtype=torch.float32) * 0.1
                    )
                    bias = None
                    if case["bias_defined"]:
                        bias = (
                            torch.randn(
                                case["weight_shape"][0],
                                dtype=torch.float32,
                            )
                            * 0.1
                        )
                        bias.requires_grad_()
                    return x, weight, bias

                def run_case(case, expect_native_route):
                    if not case.get("runtime_supported", True):
                        return
                    log_name = contract_spec_utils.contract_log_name(
                        spec,
                        case,
                        "op_hit_test.log",
                    )
                    log_path = os.path.join(os.getcwd(), log_name)
                    if os.path.exists(log_path):
                        os.remove(log_path)
                    os.environ["PYTORCH_VULKAN_OP_HIT_LOG"] = log_path

                    tensors = make_tensors(case)
                    expected = run_with_mode(case, tensors)
                    vulkan_tensors = to_vulkan_tensors(tensors)
                    torch.ops.vulkan_prepack.reset_fallback_counters()
                    actual = run_with_mode(case, vulkan_tensors)
                    torch.testing.assert_close(
                        actual.cpu(),
                        expected,
                        atol=3e-4,
                        rtol=3e-3,
                    )

                    op_hit_text = read_text(log_path)
                    if expect_native_route:
                        assert "op=aten::linear_gelu_bridge.defer" in op_hit_text, (
                            case,
                            op_hit_text,
                        )
                        assert "op=aten::linear_gelu_bridge.hit" in op_hit_text, (
                            case,
                            op_hit_text,
                        )
                        assert (
                            "op=aten::linear_gelu_bridge.materialize"
                            not in op_hit_text
                        ), (case, op_hit_text)
                        assert re.search(
                            r"op=aten::linear\\.buffer_float"
                            r"(?:_tiled)?_bias(?:_vec2)?_gelu",
                            op_hit_text,
                        ), (case, op_hit_text)
                    else:
                        for bridge_op in (
                            "op=aten::linear_gelu_bridge.defer",
                            "op=aten::linear_gelu_bridge.hit",
                            "op=aten::linear_gelu_bridge.materialize",
                        ):
                            assert bridge_op not in op_hit_text, (
                                case,
                                bridge_op,
                                op_hit_text,
                            )

                for _, case, expect_native_route in (
                    contract_spec_utils.iter_shape_envelope_contract_cases(spec)
                ):
                    run_case(case, expect_native_route)
            """
            self._run_repo_python_subprocess(
                script,
                error_prefix="LinearGeluBridge generated contract spec failed.",
            )
        finally:
            for path in case_log_paths:
                if os.path.exists(path):
                    os.remove(path)

    def test_linear_gelu_bridge_rejects_adjacent_unsupported_cases(self):
        op_hit_log_name = "linear_gelu_bridge_negative_guards_op_hit_test.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        op_hit_log_path = os.path.join(repo_root, op_hit_log_name)
        if os.path.exists(op_hit_log_path):
            os.remove(op_hit_log_path)

        try:
            script = """
                import torch
                import torch.nn.functional as F

                def run_case(
                    name,
                    x_shape,
                    weight_shape,
                    has_bias=True,
                    use_inference_mode=False,
                ):
                    torch.manual_seed(100 + len(name))
                    x = torch.randn(*x_shape, dtype=torch.float32) * 0.1
                    weight = torch.randn(*weight_shape, dtype=torch.float32) * 0.1
                    bias = None
                    if has_bias:
                        bias = torch.randn(weight_shape[0], dtype=torch.float32) * 0.1
                        bias.requires_grad_()

                    def run_cpu():
                        return F.gelu(
                            F.linear(x, weight, bias),
                            approximate="tanh",
                        )

                    def run_vulkan():
                        x_vulkan = x.to("vulkan")
                        weight_vulkan = weight.to("vulkan")
                        bias_vulkan = bias.to("vulkan") if bias is not None else None
                        return F.gelu(
                            F.linear(x_vulkan, weight_vulkan, bias_vulkan),
                            approximate="tanh",
                        ).cpu()

                    if use_inference_mode:
                        with torch.inference_mode():
                            expected = run_cpu()
                            actual = run_vulkan()
                    else:
                        with torch.no_grad():
                            expected = run_cpu()
                            actual = run_vulkan()

                    torch.testing.assert_close(actual, expected, atol=3e-4, rtol=3e-3)
                    print(name, float(actual.sum()))

                run_case("rows_below_512", (1, 511, 384), (1536, 384))
                run_case("features_not_384", (1, 512, 385), (1536, 385))
                run_case("output_not_1536", (1, 512, 384), (1024, 384))
                run_case("missing_bias", (1, 512, 384), (1536, 384), False)
                run_case(
                    "inference_mode",
                    (1, 512, 384),
                    (1536, 384),
                    use_inference_mode=True,
                )
            """

            self._run_repo_python_subprocess(
                script,
                extra_env={"PYTORCH_VULKAN_OP_HIT_LOG": op_hit_log_name},
                error_prefix="linear GELU bridge negative guard subprocess failed.",
            )

            self.assertTrue(os.path.exists(op_hit_log_path))
            with open(op_hit_log_path, "r", encoding="utf-8") as log_file:
                op_hit_text = log_file.read()

            self.assertNotIn("op=aten::linear_gelu_bridge.defer", op_hit_text)
            self.assertNotIn("op=aten::linear_gelu_bridge.hit", op_hit_text)
            self.assertNotIn("op=aten::linear_gelu_bridge.materialize", op_hit_text)
        finally:
            if os.path.exists(op_hit_log_path):
                os.remove(op_hit_log_path)

    def test_linear_gelu_bridge_materialized_input_uses_plain_gelu(self):
        op_hit_log_name = "linear_gelu_bridge_materialize_before_gelu_op_hit_test.log"
        repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
