    def test_view_then_scaled_dot_product_attention(self):
        torch.manual_seed(0)
        query = torch.randn(1, 2, 9, 8)
        key = torch.randn(1, 2, 7, 8)
        value = torch.randn(1, 2, 7, 8)

        def fn(q, k, v):
            q = q.reshape(2, 9, 8)
            k = k.reshape(2, 7, 8)
            v = v.reshape(2, 7, 8)
            return F.scaled_dot_product_attention(
                q,
                k,
                v,
                dropout_p=0.0,
                is_causal=False,
                scale=0.125)

        with self.assertRaisesRegex(RuntimeError, "KnownBadSdpaExplicitScale"):
            fn(query.to("vulkan"), key.to("vulkan"), value.to("vulkan"))

